{
  "name": "AA Pay - Smart Bill Splitter",
  "description": "An AI-powered bill splitting application that extracts items from receipt screenshots and calculates shared costs easily."
}

export interface ReceiptItem {
  id: string;
  name: string;
  price: number;
  assignedTo: string[]; // Array of participant IDs
}

export interface Participant {
  id: string;
  name: string;
  isPayer: boolean;
}

export interface BillState {
  items: ReceiptItem[];
  participants: Participant[];
  tax: number;
  discount: number;
}

export enum AppStep {
  UPLOAD = 'UPLOAD',
  EDIT_AND_ASSIGN = 'EDIT_AND_ASSIGN',
  RESULT = 'RESULT',
}

import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptItem } from "../types";

const parseReceiptImage = async (base64Image: string): Promise<Partial<ReceiptItem>[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Using gemini-2.5-flash-image for multimodal capabilities (Image -> Text)
  const modelId = "gemini-2.5-flash-image";

  const prompt = `
    Analyze this restaurant receipt or order screenshot. 
    Extract a list of individual items and their prices. 
    Ignore the total sum, taxes, or discounts for now, just the line items.
    Return a JSON array where each object has a 'name' (string) and 'price' (number).
    Ensure the price is a number (e.g., 25.5), not a string.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/png", // Assuming PNG for simplicity in this demo, though logic handles base64
              data: base64Image,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              price: { type: Type.NUMBER },
            },
            required: ["name", "price"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) return [];

    const rawItems = JSON.parse(text);

    // Add temporary IDs
    return rawItems.map((item: any) => ({
      ...item,
      id: crypto.randomUUID(),
      assignedTo: [],
    }));

  } catch (error) {
    console.error("Error parsing receipt with Gemini:", error);
    throw new Error("Failed to analyze the receipt. Please try again or enter items manually.");
  }
};

export { parseReceiptImage };

import React from 'react';

export const Spinner: React.FC = () => (
  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
  </svg>
);

import React from 'react';
import { BillState } from '../types';

interface ResultViewProps {
  state: BillState;
  onReset: () => void;
  onBack: () => void;
}

export const ResultView: React.FC<ResultViewProps> = ({ state, onReset, onBack }) => {
  const { items, participants } = state;

  const payer = participants.find(p => p.isPayer) || participants[0];

  // Calculate totals
  const totalBill = items.reduce((sum, item) => sum + item.price, 0);

  // Calculate per-person cost
  const debts: Record<string, number> = {};
  participants.forEach(p => debts[p.id] = 0);

  items.forEach(item => {
    if (item.assignedTo.length > 0) {
      const splitCost = item.price / item.assignedTo.length;
      item.assignedTo.forEach(participantId => {
        if (debts[participantId] !== undefined) {
          debts[participantId] += splitCost;
        }
      });
    } else {
      // Unassigned items - usually warn, but here we split among everyone? 
      // Or show as error. Let's assume unassigned means split equal among all.
      const splitCost = item.price / participants.length;
      participants.forEach(p => {
        debts[p.id] += splitCost;
      });
    }
  });

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-xl shadow-lg overflow-hidden flex flex-col h-[85vh]">
      <div className="bg-gradient-to-r from-green-500 to-emerald-600 p-6 text-white shrink-0">
        <h2 className="text-2xl font-bold">Calculation Result</h2>
        <p className="text-green-100 mt-1">Total Bill: <span className="font-mono font-bold text-xl">${totalBill.toFixed(2)}</span></p>
        <p className="text-sm opacity-90">Paid by: <span className="font-bold underline">{payer?.name}</span></p>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
           {participants.map(person => {
             const cost = debts[person.id];
             const isPayer = person.id === payer?.id;
             const balance = isPayer ? (totalBill - cost) : -cost; // Positive means receive, Negative means pay

             return (
               <div key={person.id} className={`border rounded-lg p-4 relative ${isPayer ? 'border-green-200 bg-green-50' : 'border-gray-200'}`}>
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="font-bold text-lg text-gray-800">{person.name} {isPayer && '(Payer)'}</h3>
                  </div>

                  <div className="space-y-1 text-sm text-gray-600">
                    <div className="flex justify-between">
                      <span>Consumed:</span>
                      <span className="font-mono font-bold">${cost.toFixed(2)}</span>
                    </div>
                  </div>

                  <div className={`mt-4 pt-3 border-t ${isPayer ? 'border-green-200' : 'border-gray-200'} flex justify-between items-center`}>
                     <span className="text-sm font-medium text-gray-500">
                       {isPayer ? 'To Receive:' : 'To Pay:'}
                     </span>
                     <span className={`text-xl font-bold font-mono ${isPayer ? 'text-green-600' : 'text-red-500'}`}>
                        ${Math.abs(balance).toFixed(2)}
                     </span>
                  </div>
               </div>
             );
           })}
        </div>

        {/* Transfer Details */}
        <div className="bg-gray-50 rounded-xl p-5 border border-gray-100">
          <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
            Transfers Required
          </h3>
          <ul className="space-y-3">
             {participants.filter(p => p.id !== payer?.id).map(p => (
               <li key={p.id} className="flex items-center justify-between bg-white p-3 rounded shadow-sm">
                 <div className="flex items-center gap-2">
                   <span className="font-medium text-red-500">{p.name}</span>
                   <span className="text-gray-400">→</span>
                   <span className="font-medium text-green-600">{payer?.name}</span>
                 </div>
                 <span className="font-mono font-bold text-gray-800">${debts[p.id].toFixed(2)}</span>
               </li>
             ))}
          </ul>
        </div>
      </div>

      <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-3 shrink-0">
        <button 
          onClick={onBack}
          className="flex-1 py-3 px-4 bg-white border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition shadow-sm"
        >
          Adjust Items
        </button>
        <button 
          onClick={onReset}
          className="flex-1 py-3 px-4 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition shadow-md"
        >
          Start Over
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { BillState, Participant, ReceiptItem } from '../types';

interface EditorViewProps {
  initialItems: Partial<ReceiptItem>[];
  onFinish: (finalState: BillState) => void;
}

export const EditorView: React.FC<EditorViewProps> = ({ initialItems, onFinish }) => {
  // Initialize items with required fields
  const [items, setItems] = useState<ReceiptItem[]>(
    initialItems.map(i => ({ 
      id: i.id || crypto.randomUUID(), 
      name: i.name || 'Unknown Item', 
      price: i.price || 0, 
      assignedTo: [] 
    }))
  );

  const [participants, setParticipants] = useState<Participant[]>([
    { id: '1', name: '403', isPayer: true },
    { id: '2', name: 'Friend A', isPayer: false },
    { id: '3', name: 'Friend B', isPayer: false },
    { id: '4', name: 'Friend C', isPayer: false },
  ]);

  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');

  const [editingPayer, setEditingPayer] = useState(false);

  // Toggle assignment of a user to an item
  const toggleAssignment = (itemId: string, participantId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;

      const isAssigned = item.assignedTo.includes(participantId);
      let newAssignedTo;
      if (isAssigned) {
        newAssignedTo = item.assignedTo.filter(id => id !== participantId);
      } else {
        newAssignedTo = [...item.assignedTo, participantId];
      }
      return { ...item, assignedTo: newAssignedTo };
    }));
  };

  const assignToAll = (itemId: string) => {
     setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      // If currently all assigned, clear all. Otherwise select all.
      const allSelected = participants.every(p => item.assignedTo.includes(p.id));
      return { ...item, assignedTo: allSelected ? [] : participants.map(p => p.id) };
     }));
  };

  const handlePayerChange = (id: string) => {
    setParticipants(prev => prev.map(p => ({
      ...p,
      isPayer: p.id === id
    })));
    setEditingPayer(false);
  };

  const addItem = () => {
    if (!newItemName || !newItemPrice) return;
    setItems([...items, {
      id: crypto.randomUUID(),
      name: newItemName,
      price: parseFloat(newItemPrice),
      assignedTo: participants.map(p => p.id) // Default to shared
    }]);
    setNewItemName('');
    setNewItemPrice('');
  };

  const deleteItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const updateParticipantName = (id: string, name: string) => {
    setParticipants(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const total = items.reduce((sum, i) => sum + i.price, 0);

  return (
    <div className="w-full max-w-4xl mx-auto h-[90vh] flex flex-col md:flex-row gap-4">

      {/* Left Column: Configuration & People */}
      <div className="w-full md:w-1/3 flex flex-col gap-4">
        {/* Payer Card */}
        <div className="bg-white p-4 rounded-xl shadow-md border border-indigo-50">
          <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wide mb-2">Who Paid?</h3>
          {editingPayer ? (
             <div className="space-y-2">
               {participants.map(p => (
                 <button 
                  key={p.id}
                  onClick={() => handlePayerChange(p.id)}
                  className={`w-full text-left px-3 py-2 rounded text-sm ${p.isPayer ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}
                 >
                   {p.name}
                 </button>
               ))}
             </div>
          ) : (
             <div className="flex justify-between items-center bg-indigo-50 p-3 rounded-lg border border-indigo-100 cursor-pointer" onClick={() => setEditingPayer(true)}>
               <span className="font-bold text-indigo-900">{participants.find(p => p.isPayer)?.name}</span>
               <span className="text-xs text-indigo-500 font-medium">Change</span>
             </div>
          )}
        </div>

        {/* Participants List */}
        <div className="bg-white p-4 rounded-xl shadow-md flex-1 overflow-hidden flex flex-col">
          <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wide mb-3">Participants ({participants.length})</h3>
          <div className="flex-1 overflow-y-auto space-y-2">
            {participants.map((p, idx) => (
              <div key={p.id} className="flex items-center gap-2">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0`} style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`}}>
                  {p.name.charAt(0)}
                </div>
                <input 
                  type="text" 
                  value={p.name}
                  onChange={(e) => updateParticipantName(p.id, e.target.value)}
                  className="flex-1 bg-transparent border-b border-transparent focus:border-indigo-300 outline-none text-gray-800 text-sm py-1"
                />
              </div>
            ))}
             <button 
                onClick={() => setParticipants([...participants, { id: crypto.randomUUID(), name: `Person ${participants.length + 1}`, isPayer: false }])}
                className="w-full mt-2 py-2 text-sm text-indigo-600 border border-dashed border-indigo-300 rounded hover:bg-indigo-50 transition"
             >
               + Add Person
             </button>
          </div>
        </div>
      </div>

      {/* Right Column: Items */}
      <div className="w-full md:w-2/3 bg-white rounded-xl shadow-md flex flex-col overflow-hidden">
        <div className="p-4 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
          <div>
            <h2 className="font-bold text-gray-800">Order Items</h2>
            <p className="text-xs text-gray-500">Tap avatars to assign</p>
          </div>
          <div className="text-right">
             <span className="text-xs text-gray-500">Total</span>
             <div className="font-mono font-bold text-xl text-indigo-600">${total.toFixed(2)}</div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
           {items.map((item) => {
             const allSelected = participants.every(p => item.assignedTo.includes(p.id));

             return (
               <div key={item.id} className="border border-gray-100 rounded-lg p-3 hover:shadow-sm transition-shadow">
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex-1 pr-2">
                      <input 
                        className="font-medium text-gray-800 w-full outline-none focus:text-indigo-600"
                        value={item.name}
                        onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, name: e.target.value} : i))}
                      />
                      <div className="text-xs text-gray-400 mt-1">
                        {item.assignedTo.length === 0 ? 'Unassigned' : 
                         allSelected ? 'Shared by Everyone' : 
                         `Shared by ${item.assignedTo.length} people`}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                       <span className="font-mono text-gray-600">$</span>
                       <input 
                         type="number"
                         className="w-20 text-right font-mono font-bold text-gray-800 border-b border-gray-200 focus:border-indigo-500 outline-none"
                         value={item.price}
                         onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, price: parseFloat(e.target.value) || 0} : i))}
                       />
                       <button onClick={() => deleteItem(item.id)} className="text-red-400 hover:text-red-600 p-1">✕</button>
                    </div>
                  </div>

                  {/* Avatar Selectors */}
                  <div className="flex flex-wrap gap-2 items-center">
                    <button 
                      onClick={() => assignToAll(item.id)}
                      className={`px-2 py-1 text-xs rounded border transition-colors ${allSelected ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'}`}
                    >
                      ALL
                    </button>
                    <div className="w-px h-6 bg-gray-200 mx-1"></div>
                    {participants.map((p, idx) => {
                      const isSelected = item.assignedTo.includes(p.id);
                      return (
                        <button
                          key={p.id}
                          onClick={() => toggleAssignment(item.id, p.id)}
                          className={`relative w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all border-2 ${isSelected ? 'border-white shadow-md scale-110' : 'opacity-40 border-transparent grayscale'}`}
                          style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`, color: 'white' }}
                          title={p.name}
                        >
                          {p.name.charAt(0)}
                          {isSelected && (
                             <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-white rounded-full flex items-center justify-center">
                               <div className="w-2 h-2 rounded-full bg-green-500"></div>
                             </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
               </div>
             );
           })}

           {/* Add Manual Item Row */}
           <div className="flex gap-2 items-center p-2 border-t border-dashed border-gray-300 mt-4">
              <input 
                placeholder="Item Name" 
                className="flex-1 p-2 border rounded text-sm"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
              />
              <input 
                type="number" 
                placeholder="0.00" 
                className="w-24 p-2 border rounded text-sm"
                value={newItemPrice}
                onChange={(e) => setNewItemPrice(e.target.value)}
              />
              <button 
                onClick={addItem}
                disabled={!newItemName || !newItemPrice}
                className="bg-gray-800 text-white px-4 py-2 rounded text-sm disabled:opacity-50"
              >
                Add
              </button>
           </div>
        </div>

        <div className="p-4 border-t border-gray-100 bg-gray-50">
          <button 
            onClick={() => onFinish({ items, participants, tax: 0, discount: 0 })}
            className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-lg shadow-lg transition-transform transform active:scale-[0.99]"
          >
            Calculate Split
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState } from 'react';
import { Spinner } from './Spinner';

interface ReceiptUploaderProps {
  onImageSelected: (base64: string) => Promise<void>;
  isProcessing: boolean;
}

export const ReceiptUploader: React.FC<ReceiptUploaderProps> = ({ onImageSelected, isProcessing }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragActive, setDragActive] = useState(false);

  const handleFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
      alert('Please upload an image file');
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      // Remove data URL prefix for API
      const base64Data = base64.split(',')[1]; 
      await onImageSelected(base64Data);
    };
    reader.readAsDataURL(file);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(true);
  };

  const onDragLeave = () => {
    setDragActive(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  return (
    <div className="w-full max-w-lg mx-auto text-center">
      <div 
        className={`
          relative border-2 border-dashed rounded-2xl p-10 transition-all duration-300
          ${dragActive ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 bg-white'}
          ${isProcessing ? 'opacity-80 pointer-events-none' : 'hover:border-indigo-400'}
        `}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
      >
        <input 
          type="file" 
          ref={fileInputRef}
          className="hidden" 
          accept="image/*"
          onChange={(e) => e.target.files && handleFile(e.target.files[0])}
        />

        {isProcessing ? (
          <div className="flex flex-col items-center justify-center py-8">
            <div className="bg-indigo-600 p-3 rounded-full mb-4 shadow-lg shadow-indigo-200">
               <Spinner />
            </div>
            <h3 className="text-xl font-bold text-gray-800">Analyzing Receipt...</h3>
            <p className="text-gray-500 mt-2">Our AI is extracting items and prices.</p>
          </div>
        ) : (
          <div className="flex flex-col items-center py-4">
             <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center mb-4 text-indigo-600">
               <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
             </div>
             <h3 className="text-lg font-bold text-gray-800 mb-2">Upload Receipt</h3>
             <p className="text-gray-500 text-sm mb-6 max-w-xs">Drag & drop your order screenshot here, or click to browse.</p>
             <button 
               onClick={() => fileInputRef.current?.click()}
               className="bg-gray-900 text-white px-6 py-3 rounded-lg font-semibold shadow-lg hover:bg-gray-800 transition transform active:scale-95"
             >
               Select Image
             </button>
          </div>
        )}
      </div>

      {!isProcessing && (
        <button 
          onClick={() => onImageSelected('')} // Pass empty to skip AI
          className="mt-6 text-indigo-600 font-medium text-sm hover:underline"
        >
          Skip and enter manually
        </button>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { AppStep, BillState, ReceiptItem } from './types';
import { ReceiptUploader } from './components/ReceiptUploader';
import { EditorView } from './components/EditorView';
import { ResultView } from './components/ResultView';
import { parseReceiptImage } from './services/geminiService';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [initialItems, setInitialItems] = useState<Partial<ReceiptItem>[]>([]);
  const [finalState, setFinalState] = useState<BillState | null>(null);

  const handleImageUpload = async (base64Data: string) => {
    if (!base64Data) {
      // Manual mode
      setInitialItems([]);
      setStep(AppStep.EDIT_AND_ASSIGN);
      return;
    }

    setIsProcessing(true);
    try {
      const items = await parseReceiptImage(base64Data);
      setInitialItems(items);
      setStep(AppStep.EDIT_AND_ASSIGN);
    } catch (error) {
      alert("Failed to read receipt. Please try again or enter manually.");
      console.error(error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleEditorFinish = (state: BillState) => {
    setFinalState(state);
    setStep(AppStep.RESULT);
  };

  const handleReset = () => {
    setStep(AppStep.UPLOAD);
    setInitialItems([]);
    setFinalState(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-white to-purple-50 text-gray-800 font-sans selection:bg-indigo-100">

      {/* Header */}
      <header className="p-6">
        <div className="max-w-7xl mx-auto flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg">
            AA
          </div>
          <h1 className="text-xl font-bold tracking-tight text-gray-900">SplitIt</h1>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-6 flex flex-col items-center justify-center min-h-[80vh]">

        {step === AppStep.UPLOAD && (
          <div className="w-full animate-fade-in-up">
            <div className="text-center mb-10">
              <h2 className="text-4xl font-extrabold text-gray-900 mb-4">Splitting bills made effortless.</h2>
              <p className="text-lg text-gray-600 max-w-2xl mx-auto">
                Upload a screenshot of your food order or receipt. We'll extract the items, you pick who ate what, and we calculate the rest.
              </p>
            </div>
            <ReceiptUploader onImageSelected={handleImageUpload} isProcessing={isProcessing} />
          </div>
        )}

        {step === AppStep.EDIT_AND_ASSIGN && (
          <div className="w-full animate-fade-in">
             <EditorView initialItems={initialItems} onFinish={handleEditorFinish} />
          </div>
        )}

        {step === AppStep.RESULT && finalState && (
          <div className="w-full animate-fade-in">
            <ResultView 
              state={finalState} 
              onReset={handleReset} 
              onBack={() => setStep(AppStep.EDIT_AND_ASSIGN)} 
            />
          </div>
        )}

      </main>

      {/* Footer */}
      <footer className="p-6 text-center text-sm text-gray-400">
        Powered by Gemini • Secure & Private
      </footer>

    </div>
  );
};

