import { GoogleGenAI, Type } from "@google/genai";
import { ReceiptItem } from "../types";

const parseReceiptImage = async (base64Image: string): Promise<Partial<ReceiptItem>[]> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Use gemini-3-flash-preview which supports both image input and JSON schema enforcement
  const modelId = "gemini-3-flash-preview";

  const prompt = `
    Analyze this restaurant receipt or order screenshot. 
    Extract a list of individual items and their prices. 
    Ignore the total sum, taxes, or discounts for now, just the line items.
    Return a JSON array where each object has a 'name' (string) and 'price' (number).
    Ensure the price is a number (e.g., 25.5), not a string.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "image/png", 
              data: base64Image,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              price: { type: Type.NUMBER },
            },
            required: ["name", "price"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) return [];

    let rawItems;
    try {
      rawItems = JSON.parse(text);
    } catch (e) {
      console.warn("JSON parse failed, attempting regex cleanup", text);
      const match = text.match(/\[.*\]/s);
      if (match) {
        rawItems = JSON.parse(match[0]);
      } else {
        throw new Error("Could not parse response as JSON");
      }
    }

    // Add temporary IDs
    return rawItems.map((item: any) => ({
      ...item,
      id: crypto.randomUUID(),
      assignedTo: [],
    }));

  } catch (error) {
    console.error("Error parsing receipt with Gemini:", error);
    throw new Error("Failed to analyze the receipt. Please try again or enter items manually.");
  }
};

