                      </span>
                    </div>
                    <div className="flex justify-between">
                      <span>应付金额:</span>
                      <span className="font-mono font-bold">¥{cost.toFixed(2)}</span>
                    </div>
                  </div>

                  <div className={`mt-4 pt-3 border-t ${isPayer ? 'border-green-200' : 'border-gray-200'} flex justify-between items-center`}>
                     <span className="text-sm font-medium text-gray-500">
                       {isPayer ? '应收:' : '需支付:'}
                     </span>
                     <span className={`text-xl font-bold font-mono ${isPayer ? 'text-green-600' : 'text-red-500'}`}>
                        ¥{Math.abs(balance).toFixed(2)}
                     </span>
                  </div>
               </div>
             );
           })}
        </div>

        {/* Transfer Details */}
        <div className="bg-gray-50 rounded-xl p-5 border border-gray-100">
          <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
            转账方案
          </h3>
          <ul className="space-y-3">
             {participants.filter(p => p.id !== payer?.id).map(p => {
               const amount = finalDebts[p.id];
               if (amount <= 0.01) return null; // Skip tiny amounts
               return (
                 <li key={p.id} className="flex items-center justify-between bg-white p-3 rounded shadow-sm">
                   <div className="flex items-center gap-2">
                     <span className="font-medium text-red-500">{p.name}</span>
                     <span className="text-gray-400">→</span>
                     <span className="font-medium text-green-600">{payer?.name}</span>
                   </div>
                   <span className="font-mono font-bold text-gray-800">¥{amount.toFixed(2)}</span>
                 </li>
               );
             })}
          </ul>
        </div>
      </div>

      <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-3 shrink-0">
        <button 
          onClick={onBack}
          className="flex-1 py-3 px-4 bg-white border border-gray-300 text-gray-700 font-semibold rounded-lg hover:bg-gray-50 transition shadow-sm"
        >
          修改订单
        </button>
        <button 
          onClick={onReset}
          className="flex-1 py-3 px-4 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition shadow-md"
        >
          重新开始
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { AppStep, BillState, ReceiptItem } from './types';
import { ReceiptUploader } from './components/ReceiptUploader';
import { EditorView } from './components/EditorView';
import { ResultView } from './components/ResultView';
import { parseReceiptImage } from './services/geminiService';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);
  const [initialItems, setInitialItems] = useState<Partial<ReceiptItem>[]>([]);
  const [finalState, setFinalState] = useState<BillState | null>(null);

  const handleImageUpload = async (base64Data: string) => {
    if (!base64Data) {
      // Manual mode
      setInitialItems([]);
      setFinalState(null); // Clear previous state when starting fresh
      setStep(AppStep.EDIT_AND_ASSIGN);
      return;
    }

    setIsProcessing(true);
    try {
      const items = await parseReceiptImage(base64Data);
      setInitialItems(items);
      setFinalState(null); // Clear previous state on new upload
      setStep(AppStep.EDIT_AND_ASSIGN);
    } catch (error) {
      alert("识别小票失败，请重试或手动输入。");
      console.error(error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleEditorFinish = (state: BillState) => {
    setFinalState(state);
    setStep(AppStep.RESULT);
  };

  const handleReset = () => {
    setStep(AppStep.UPLOAD);
    setInitialItems([]);
    setFinalState(null);
  };

  return (
    <div className="fixed inset-0 bg-gray-50 text-gray-800 font-sans flex flex-col overflow-hidden">

      {/* Header - Compact on mobile */}
      <header className="px-4 py-3 md:p-6 bg-white shadow-sm shrink-0 z-20 relative">
        <div className="max-w-7xl mx-auto flex items-center gap-3">
          <div className="w-8 h-8 md:w-10 md:h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg">
            AA
          </div>
          <h1 className="text-lg md:text-xl font-bold tracking-tight text-gray-900">AA Pay</h1>
        </div>
      </header>

      {/* Main Content Area - Scrollable Container */}
      <main className="flex-1 overflow-hidden relative w-full max-w-5xl mx-auto md:p-6">

        {step === AppStep.UPLOAD && (
          <div className="w-full h-full overflow-y-auto p-4 animate-fade-in-up">
            <div className="text-center mb-6 md:mb-10 mt-4 md:mt-10">
              <h2 className="text-2xl md:text-4xl font-extrabold text-gray-900 mb-2 md:mb-4">轻松搞定聚餐算账</h2>
              <p className="text-sm md:text-lg text-gray-600 max-w-2xl mx-auto">
                上传小票截图或照片，AI 自动识别菜品，简单勾选谁吃了什么。
              </p>
            </div>
            <ReceiptUploader onImageSelected={handleImageUpload} isProcessing={isProcessing} />
          </div>
        )}

        {step === AppStep.EDIT_AND_ASSIGN && (
          <div className="w-full h-full animate-fade-in">
             <EditorView 
                initialItems={initialItems} 
                existingState={finalState} 
                onFinish={handleEditorFinish} 
             />
          </div>
        )}

        {step === AppStep.RESULT && finalState && (
          <div className="w-full h-full animate-fade-in">
            <ResultView 
              state={finalState} 
              onReset={handleReset} 
              onBack={() => setStep(AppStep.EDIT_AND_ASSIGN)} 
            />
          </div>
        )}

      </main>

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { BillState, Participant, ReceiptItem } from '../types';

interface EditorViewProps {
  initialItems: Partial<ReceiptItem>[];
  existingState?: BillState | null;
  onFinish: (finalState: BillState) => void;
}

const DEFAULT_PARTICIPANTS = [
  { id: '1', name: '我', isPayer: true },
  { id: '2', name: '朋友 A', isPayer: false },
  { id: '3', name: '朋友 B', isPayer: false },
  { id: '4', name: '朋友 C', isPayer: false },
];

export const EditorView: React.FC<EditorViewProps> = ({ initialItems, existingState, onFinish }) => {
  const [participants, setParticipants] = useState<Participant[]>(
    existingState?.participants || DEFAULT_PARTICIPANTS
  );

  const [items, setItems] = useState<ReceiptItem[]>(() => {
    if (existingState && existingState.items.length > 0) {
      return existingState.items;
    }
    return initialItems.map(i => ({ 
      id: i.id || crypto.randomUUID(), 
      name: i.name || '未知商品', 
      price: i.price || 0, 
      assignedTo: participants.map(p => p.id) 
    }));
  });

  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');

  const itemsTotal = items.reduce((sum, i) => sum + i.price, 0);

  const [grandTotalInput, setGrandTotalInput] = useState<string>('');

  useEffect(() => {
    if (existingState && grandTotalInput === '') {
        const total = itemsTotal + existingState.tax;
        setGrandTotalInput(total.toFixed(2));
    }
    else if (grandTotalInput === '' && itemsTotal > 0) {
      setGrandTotalInput(itemsTotal.toFixed(2));
    }
  }, [itemsTotal, existingState]);

  const [editingPayer, setEditingPayer] = useState(false);
  const [isPeopleExpanded, setIsPeopleExpanded] = useState(false);

  const toggleAssignment = (itemId: string, participantId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const isAssigned = item.assignedTo.includes(participantId);
      const newAssignedTo = isAssigned 
        ? item.assignedTo.filter(id => id !== participantId) 
        : [...item.assignedTo, participantId];
      return { ...item, assignedTo: newAssignedTo };
    }));
  };

  const assignToAll = (itemId: string) => {
     setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const allSelected = participants.every(p => item.assignedTo.includes(p.id));
      return { ...item, assignedTo: allSelected ? [] : participants.map(p => p.id) };
     }));
  };

  const handlePayerChange = (id: string) => {
    setParticipants(prev => prev.map(p => ({ ...p, isPayer: p.id === id })));
    setEditingPayer(false);
  };

  const addItem = () => {
    if (!newItemName || !newItemPrice) return;
    setItems([...items, {
      id: crypto.randomUUID(),
      name: newItemName,
      price: parseFloat(newItemPrice),
      assignedTo: participants.map(p => p.id)
    }]);
    setNewItemName('');
    setNewItemPrice('');
  };

  const deleteItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const updateParticipantName = (id: string, name: string) => {
    setParticipants(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleFinish = () => {
    const finalGrandTotal = parseFloat(grandTotalInput) || itemsTotal;
    const taxAndTip = finalGrandTotal - itemsTotal;
    onFinish({ items, participants, tax: taxAndTip, discount: 0 });
  };

  return (
    <div className="w-full h-full flex flex-col md:flex-row gap-4 md:bg-transparent bg-gray-50">

      {/* Left Column: People (Mobile: Collapsible/Scrollable top section) */}
      <div className={`
        bg-white shadow-sm md:shadow-md md:rounded-xl shrink-0 
        flex flex-col md:w-1/3 transition-all duration-300 z-10
        ${isPeopleExpanded ? 'max-h-[60vh]' : 'max-h-[30vh]'} md:max-h-full md:h-full
      `}>
        {/* Mobile Toggle Handle */}
        <div 
          className="md:hidden flex justify-center pt-2 pb-1 cursor-pointer bg-gray-50 border-b border-gray-200"
          onClick={() => setIsPeopleExpanded(!isPeopleExpanded)}
        >
           <div className="w-10 h-1 bg-gray-300 rounded-full"></div>
        </div>

        <div className="p-4 overflow-y-auto">
          {/* Payer Section */}
          <div className="mb-4">
             <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-2">谁付的款 (Payer)</h3>
             {editingPayer ? (
                <div className="space-y-1">
                  {participants.map(p => (
                    <button 
                     key={p.id}
                     onClick={() => handlePayerChange(p.id)}
                     className={`w-full text-left px-3 py-2 rounded text-sm ${p.isPayer ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}
                    >
                      {p.name}
                    </button>
                  ))}
                </div>
             ) : (
                <div className="flex justify-between items-center bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100 cursor-pointer" onClick={() => setEditingPayer(true)}>
                  <div className="flex items-center gap-2">
                     <span className="text-xs text-indigo-400">当前:</span>
                     <span className="font-bold text-indigo-900 text-sm">{participants.find(p => p.isPayer)?.name}</span>
                  </div>
                  <span className="text-xs text-indigo-500 font-medium">更改</span>
                </div>
             )}
          </div>

          {/* Participants List */}
          <div>
            <div className="flex justify-between items-center mb-2">
               <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide">参与者 ({participants.length})</h3>
            </div>
            <div className="space-y-2">
              {participants.map((p, idx) => (
                <div key={p.id} className="flex items-center gap-2 bg-gray-50/50 p-1.5 rounded-lg border border-transparent hover:border-gray-200 focus-within:border-indigo-300 transition-colors">
                  <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-sm`} style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`}}>
                    {p.name.charAt(0)}
                  </div>
                  <input 
                    type="text" 
                    value={p.name}
                    onChange={(e) => updateParticipantName(p.id, e.target.value)}
                    className="flex-1 bg-transparent border-none outline-none text-gray-800 text-sm p-0 focus:ring-0"
                    placeholder="Name"
                  />
                </div>
              ))}
               <button 
                  onClick={() => setParticipants([...participants, { id: crypto.randomUUID(), name: `朋友 ${participants.length}`, isPayer: false }])}
                  className="w-full mt-1 py-1.5 text-xs text-indigo-600 border border-dashed border-indigo-300 rounded hover:bg-indigo-50 transition"
               >
                 + 添加人员
               </button>
            </div>
          </div>
        </div>
      </div>

      {/* Right Column: Items (Fills remaining space) */}
      <div className="flex-1 bg-white md:rounded-xl shadow-sm md:shadow-md flex flex-col min-h-0 overflow-hidden relative">
        {/* Items Header */}
        <div className="px-4 py-3 border-b border-gray-100 bg-white shrink-0 flex justify-between items-center z-10">
          <div>
            <h2 className="font-bold text-gray-800 text-sm md:text-base">订单详情</h2>
            <p className="text-[10px] md:text-xs text-gray-500">点击下方头像分配</p>
          </div>
          <div className="text-right">
             <span className="text-xs text-gray-500 mr-2">小计:</span>
             <span className="font-mono font-bold text-base md:text-lg text-gray-700">¥{itemsTotal.toFixed(2)}</span>
          </div>
        </div>

        {/* Scrollable Items List */}
        <div className="flex-1 overflow-y-auto p-3 md:p-4 space-y-3 pb-24 md:pb-4">
           {items.map((item) => {
             const allSelected = participants.every(p => item.assignedTo.includes(p.id));

             return (
               <div key={item.id} className="bg-white border border-gray-100 rounded-lg p-3 shadow-sm">
                  <div className="flex justify-between items-start mb-2 gap-2">
                    <div className="flex-1 min-w-0">
                      <input 
                        className="font-medium text-gray-800 w-full outline-none focus:text-indigo-600 text-sm md:text-base bg-transparent truncate"
                        value={item.name}
                        onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, name: e.target.value} : i))}
                        placeholder="商品名称"
                      />
                      <div className="text-[10px] md:text-xs text-gray-400 mt-0.5 truncate">
                        {item.assignedTo.length === 0 ? '未分配' : 
                         allSelected ? '所有人' : 
                         participants.filter(p => item.assignedTo.includes(p.id)).map(p => p.name).join(', ')}
                      </div>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                       <span className="font-mono text-gray-400 text-xs">¥</span>
                       <input 
                         type="number"
                         className="w-16 text-right font-mono font-bold text-gray-800 border-b border-gray-200 focus:border-indigo-500 outline-none text-sm md:text-base p-0"
                         value={item.price}
                         onFocus={(e) => e.target.select()}
                         onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, price: parseFloat(e.target.value) || 0} : i))}
                       />
                    </div>
                    <button onClick={() => deleteItem(item.id)} className="text-gray-300 hover:text-red-500 p-1 -mt-1 -mr-1">
                         <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>

                  {/* Avatar Selectors */}
                  <div className="flex flex-wrap gap-1.5 items-center mt-2">
                    <button 
                      onClick={() => assignToAll(item.id)}
                      className={`px-2 py-0.5 text-[10px] font-bold rounded border transition-colors ${allSelected ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-gray-50 text-gray-500 border-gray-200 hover:bg-gray-100'}`}
                    >
                      ALL
                    </button>
                    <div className="w-px h-5 bg-gray-200 mx-0.5"></div>
                    {participants.map((p, idx) => {
                      const isSelected = item.assignedTo.includes(p.id);
                      return (
                        <button
                          key={p.id}
                          onClick={() => toggleAssignment(item.id, p.id)}
                          className={`relative w-7 h-7 md:w-8 md:h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all border-2 ${isSelected ? 'border-white shadow-md scale-105' : 'opacity-40 border-transparent grayscale'}`}
                          style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`, color: 'white' }}
                        >
                          {p.name.charAt(0)}
                          {isSelected && (
                             <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-white rounded-full flex items-center justify-center">
                               <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                             </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
               </div>
             );
           })}

           {/* Add Manual Item Row */}
           <div className="flex gap-2 items-center p-3 border border-dashed border-gray-300 rounded-lg bg-gray-50/50 mt-4">
              <input 
                placeholder="添加商品..." 
                className="flex-1 bg-transparent border-none text-sm outline-none"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
              />
              <input 
                type="number" 
                placeholder="0.00" 
                className="w-20 bg-transparent border-b border-gray-300 text-right text-sm outline-none"
                value={newItemPrice}
                onChange={(e) => setNewItemPrice(e.target.value)}
              />
              <button 
                onClick={addItem}
                disabled={!newItemName || !newItemPrice}
                className="bg-gray-800 text-white w-8 h-8 rounded-full flex items-center justify-center text-lg shadow hover:bg-gray-700 disabled:opacity-50 disabled:shadow-none transition-all"
              >
                +
              </button>
           </div>
        </div>

        {/* Footer: Grand Total (Fixed at bottom on mobile via flex layout + z-index) */}
        <div className="shrink-0 p-4 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
           <div className="flex justify-between items-center mb-3">
              <label className="text-sm font-bold text-gray-900">实付总金额:</label>
              <div className="flex items-center gap-2">
                 <span className="font-mono text-indigo-600 font-bold">¥</span>
                 <input 
                    type="number" 
                    className="w-24 text-right font-mono font-bold text-xl text-indigo-600 bg-indigo-50 border border-indigo-100 rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    value={grandTotalInput}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) => setGrandTotalInput(e.target.value)}
                 />
              </div>
           </div>

           {(parseFloat(grandTotalInput) || itemsTotal) !== itemsTotal && (
              <div className="text-right text-[10px] md:text-xs text-indigo-500 mb-3 font-medium">
                 {(parseFloat(grandTotalInput) || 0) > itemsTotal ? '+' : ''}
                 ¥{( (parseFloat(grandTotalInput) || 0) - itemsTotal ).toFixed(2)} (税费/优惠)
              </div>
           )}

          <button 
            onClick={handleFinish}
            className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-bold text-base rounded-xl shadow-lg shadow-indigo-200 transition-all transform active:scale-[0.98]"
          >
            开始计算 AA
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { BillState } from '../types';

interface ResultViewProps {
  state: BillState;
  onReset: () => void;
  onBack: () => void;
}

export const ResultView: React.FC<ResultViewProps> = ({ state, onReset, onBack }) => {
  const { items, participants, tax } = state;

  const payer = participants.find(p => p.isPayer) || participants[0];

  // Calculate totals
  const itemsTotal = items.reduce((sum, item) => sum + item.price, 0);
  const totalBill = itemsTotal + tax; 

  // 1. Calculate Raw Cost per person
  const rawDebts: Record<string, number> = {};
  participants.forEach(p => rawDebts[p.id] = 0);

  items.forEach(item => {
    if (item.assignedTo.length > 0) {
      const splitCost = item.price / item.assignedTo.length;
      item.assignedTo.forEach(participantId => {
        if (rawDebts[participantId] !== undefined) {
          rawDebts[participantId] += splitCost;
        }
      });
    } else {
      const splitCost = item.price / participants.length;
      participants.forEach(p => {
        rawDebts[p.id] += splitCost;
      });
    }
  });

  // 2. Distribute Total Bill proportionally
  const finalDebts: Record<string, number> = {};

  if (itemsTotal === 0) {
      const split = totalBill / participants.length;
      participants.forEach(p => finalDebts[p.id] = split);
  } else {
      const ratio = totalBill / itemsTotal;
      participants.forEach(p => {
          finalDebts[p.id] = rawDebts[p.id] * ratio;
      });
  }

  return (
    <div className="w-full h-full md:h-[85vh] max-w-2xl mx-auto bg-white md:rounded-xl shadow-lg overflow-hidden flex flex-col md:border border-gray-100">

      {/* Header Result Card */}
      <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 md:p-8 text-white shrink-0 shadow-md z-10">
        <h2 className="text-xl md:text-2xl font-bold opacity-90 mb-6">计算结果</h2>
        <div className="flex justify-between items-end">
            <div>
                <p className="text-indigo-200 text-xs md:text-sm uppercase tracking-wider mb-1">账单总额</p>
                <div className="flex items-baseline gap-1">
                    <span className="text-2xl">¥</span>
                    <span className="font-mono font-bold text-4xl md:text-5xl">{totalBill.toFixed(2)}</span>
                </div>
            </div>
            <div className="text-right">
                 <div className="inline-block bg-white/20 backdrop-blur-sm rounded-lg px-3 py-1">
                     <p className="text-[10px] text-indigo-100 mb-0.5">付款人</p>
                     <p className="font-bold text-base md:text-lg">{payer?.name}</p>
                 </div>
            </div>
        </div>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 bg-gray-50">

        {/* Person Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
           {participants.map(person => {
             const cost = finalDebts[person.id];
             const isPayer = person.id === payer?.id;
             const balance = isPayer ? (totalBill - cost) : -cost; 

             return (
               <div key={person.id} className={`rounded-xl p-4 relative shadow-sm transition-shadow border ${isPayer ? 'bg-white border-green-200 ring-1 ring-green-100' : 'bg-white border-gray-100'}`}>
                  <div className="flex justify-between items-center mb-3">
                    <div className="flex items-center gap-2">
                        <div className={`w-2 h-8 rounded-full ${isPayer ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                        <h3 className="font-bold text-base text-gray-800">{person.name}</h3>
                    </div>
                    {isPayer && <span className="bg-green-100 text-green-700 text-[10px] font-bold px-2 py-0.5 rounded-full">已付款</span>}
                  </div>

                  <div className="flex justify-between items-end">
                      <div>
                        <p className="text-xs text-gray-400 mb-0.5">应承担</p>
                        <p className="font-mono font-bold text-gray-700">¥{cost.toFixed(2)}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-xs font-medium text-gray-400 mb-0.5">
                            {isPayer ? '应收回' : '需支付'}
                        </p>
                        <p className={`font-mono font-bold text-xl ${isPayer ? 'text-green-600' : 'text-red-500'}`}>
                            ¥{Math.abs(balance).toFixed(2)}
                        </p>
                      </div>
                  </div>
               </div>
             );
           })}
        </div>

        {/* Transfer Scheme */}
        <div className="bg-white rounded-xl p-5 border border-gray-200 shadow-sm">
          <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2 text-sm uppercase tracking-wide">
            <svg className="w-4 h-4 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
            转账方案
          </h3>
          <ul className="space-y-3">
             {participants.filter(p => p.id !== payer?.id).map(p => {
               const amount = finalDebts[p.id];
               if (amount <= 0.01) return null; 
               return (
                 <li key={p.id} className="flex items-center justify-between border-b border-gray-50 pb-2 last:border-0 last:pb-0">
                   <div className="flex items-center gap-2 text-sm">
                     <span className="font-bold text-gray-800">{p.name}</span>
                     <span className="text-gray-400 text-xs">支付给</span>
                     <span className="font-bold text-gray-800">{payer?.name}</span>
                   </div>
                   <span className="font-mono font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded text-sm">¥{amount.toFixed(2)}</span>
                 </li>
               );
             })}
          </ul>
        </div>
      </div>

      {/* Footer Actions */}
      <div className="p-4 bg-white border-t border-gray-100 flex gap-3 shrink-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
        <button 
          onClick={onBack}
          className="flex-1 py-3 px-4 bg-white border border-gray-200 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 active:bg-gray-100 transition shadow-sm text-sm md:text-base"
        >
          修改订单
        </button>
        <button 
          onClick={onReset}
          className="flex-1 py-3 px-4 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 active:bg-indigo-800 transition shadow-md shadow-indigo-200 text-sm md:text-base"
        >
          重新开始
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { BillState, Participant, ReceiptItem } from '../types';

interface EditorViewProps {
  initialItems: Partial<ReceiptItem>[];
  existingState?: BillState | null;
  onFinish: (finalState: BillState) => void;
}

const DEFAULT_PARTICIPANTS = [
  { id: '1', name: '我', isPayer: true },
  { id: '2', name: '朋友 A', isPayer: false },
  { id: '3', name: '朋友 B', isPayer: false },
  { id: '4', name: '朋友 C', isPayer: false },
];

export const EditorView: React.FC<EditorViewProps> = ({ initialItems, existingState, onFinish }) => {
  const [participants, setParticipants] = useState<Participant[]>(
    existingState?.participants || DEFAULT_PARTICIPANTS
  );

  const [items, setItems] = useState<ReceiptItem[]>(() => {
    if (existingState && existingState.items.length > 0) {
      return existingState.items;
    }
    return initialItems.map(i => ({ 
      id: i.id || crypto.randomUUID(), 
      name: i.name || '未知商品', 
      price: i.price || 0, 
      assignedTo: participants.map(p => p.id) 
    }));
  });

  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');

  const itemsTotal = items.reduce((sum, i) => sum + i.price, 0);

  const [grandTotalInput, setGrandTotalInput] = useState<string>('');

  useEffect(() => {
    if (existingState && grandTotalInput === '') {
        const total = itemsTotal + existingState.tax;
        setGrandTotalInput(total.toFixed(2));
    }
    else if (grandTotalInput === '' && itemsTotal > 0) {
      setGrandTotalInput(itemsTotal.toFixed(2));
    }
  }, [itemsTotal, existingState]);

  const [editingPayer, setEditingPayer] = useState(false);
  const [isPeopleExpanded, setIsPeopleExpanded] = useState(false);

  const toggleAssignment = (itemId: string, participantId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const isAssigned = item.assignedTo.includes(participantId);
      const newAssignedTo = isAssigned 
        ? item.assignedTo.filter(id => id !== participantId) 
        : [...item.assignedTo, participantId];
      return { ...item, assignedTo: newAssignedTo };
    }));
  };

  const assignToAll = (itemId: string) => {
     setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const allSelected = participants.every(p => item.assignedTo.includes(p.id));
      return { ...item, assignedTo: allSelected ? [] : participants.map(p => p.id) };
     }));
  };

  const handlePayerChange = (id: string) => {
    setParticipants(prev => prev.map(p => ({ ...p, isPayer: p.id === id })));
    setEditingPayer(false);
  };

  const addItem = () => {
    if (!newItemName || !newItemPrice) return;
    setItems([...items, {
      id: crypto.randomUUID(),
      name: newItemName,
      price: parseFloat(newItemPrice),
      assignedTo: participants.map(p => p.id)
    }]);
    setNewItemName('');
    setNewItemPrice('');
  };

  const deleteItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const updateParticipantName = (id: string, name: string) => {
    setParticipants(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleFinish = () => {
    const finalGrandTotal = parseFloat(grandTotalInput) || itemsTotal;
    const taxAndTip = finalGrandTotal - itemsTotal;
    onFinish({ items, participants, tax: taxAndTip, discount: 0 });
  };

  return (
    <div className="w-full h-full flex flex-col md:flex-row gap-4 md:bg-transparent bg-gray-50">

      {/* Left Column: People (Mobile: Collapsible/Scrollable top section) */}
      <div className={`
        bg-white shadow-sm md:shadow-md md:rounded-xl shrink-0 
        flex flex-col md:w-1/3 transition-all duration-300 z-10
        ${isPeopleExpanded ? 'max-h-[60vh]' : 'max-h-[30vh]'} md:max-h-full md:h-full
      `}>
        {/* Mobile Toggle Handle */}
        <div 
          className="md:hidden flex justify-center pt-2 pb-1 cursor-pointer bg-gray-50 border-b border-gray-200"
          onClick={() => setIsPeopleExpanded(!isPeopleExpanded)}
        >
           <div className="w-10 h-1 bg-gray-300 rounded-full"></div>
        </div>

        <div className="p-4 overflow-y-auto">
          {/* Payer Section */}
          <div className="mb-4">
             <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-2">谁付的款 (Payer)</h3>
             {editingPayer ? (
                <div className="space-y-1">
                  {participants.map(p => (
                    <button 
                     key={p.id}
                     onClick={() => handlePayerChange(p.id)}
                     className={`w-full text-left px-3 py-2 rounded text-sm ${p.isPayer ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}
                    >
                      {p.name}
                    </button>
                  ))}
                </div>
             ) : (
                <div className="flex justify-between items-center bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100 cursor-pointer" onClick={() => setEditingPayer(true)}>
                  <div className="flex items-center gap-2">
                     <span className="text-xs text-indigo-400">当前:</span>
                     <span className="font-bold text-indigo-900 text-sm">{participants.find(p => p.isPayer)?.name}</span>
                  </div>
                  <span className="text-xs text-indigo-500 font-medium">更改</span>
                </div>
             )}
          </div>

          {/* Participants List */}
          <div>
            <div className="flex justify-between items-center mb-2">
               <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide">参与者 ({participants.length})</h3>
            </div>
            <div className="space-y-2">
              {participants.map((p, idx) => (
                <div key={p.id} className="flex items-center gap-2 bg-gray-50/50 p-1.5 rounded-lg border border-transparent hover:border-gray-200 focus-within:border-indigo-300 transition-colors">
                  <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-sm`} style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`}}>
                    {p.name.charAt(0)}
                  </div>
                  <input 
                    type="text" 
                    value={p.name}
                    onChange={(e) => updateParticipantName(p.id, e.target.value)}
                    className="flex-1 bg-transparent border-none outline-none text-gray-800 text-sm p-0 focus:ring-0"
                    placeholder="Name"
                  />
                </div>
              ))}
               <button 
                  onClick={() => setParticipants([...participants, { id: crypto.randomUUID(), name: `朋友 ${participants.length}`, isPayer: false }])}
                  className="w-full mt-1 py-1.5 text-xs text-indigo-600 border border-dashed border-indigo-300 rounded hover:bg-indigo-50 transition"
               >
                 + 添加人员
               </button>
            </div>
          </div>
        </div>
      </div>

      {/* Right Column: Items (Fills remaining space) */}
      <div className="flex-1 bg-white md:rounded-xl shadow-sm md:shadow-md flex flex-col min-h-0 overflow-hidden relative">
        {/* Items Header */}
        <div className="px-4 py-3 border-b border-gray-100 bg-white shrink-0 flex justify-between items-center z-10">
          <div>
            <h2 className="font-bold text-gray-800 text-sm md:text-base">订单详情</h2>
            <p className="text-[10px] md:text-xs text-gray-500">点击下方头像分配</p>
          </div>
          <div className="text-right">
             <span className="text-xs text-gray-500 mr-2">小计:</span>
             <span className="font-mono font-bold text-base md:text-lg text-gray-700">¥{itemsTotal.toFixed(2)}</span>
          </div>
        </div>

        {/* Scrollable Items List */}
        <div className="flex-1 overflow-y-auto p-3 md:p-4 space-y-3 pb-24 md:pb-4">
           {items.map((item) => {
             const allSelected = participants.every(p => item.assignedTo.includes(p.id));

             return (
               <div key={item.id} className="bg-white border border-gray-100 rounded-lg p-3 shadow-sm">
                  <div className="flex justify-between items-start mb-2 gap-2">
                    <div className="flex-1 min-w-0">
                      <input 
                        className="font-medium text-gray-800 w-full outline-none focus:text-indigo-600 text-sm md:text-base bg-transparent truncate"
                        value={item.name}
                        onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, name: e.target.value} : i))}
                        placeholder="商品名称"
                      />
                      <div className="text-[10px] md:text-xs text-gray-400 mt-0.5 truncate">
                        {item.assignedTo.length === 0 ? '未分配' : 
                         allSelected ? '所有人' : 
                         participants.filter(p => item.assignedTo.includes(p.id)).map(p => p.name).join(', ')}
                      </div>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                       <span className="font-mono text-gray-400 text-xs">¥</span>
                       <input 
                         type="number"
                         className="w-16 text-right font-mono font-bold text-gray-800 border-b border-gray-200 focus:border-indigo-500 outline-none text-sm md:text-base p-0"
                         value={item.price}
                         onFocus={(e) => e.target.select()}
                         onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, price: parseFloat(e.target.value) || 0} : i))}
                       />
                    </div>
                    <button onClick={() => deleteItem(item.id)} className="text-gray-300 hover:text-red-500 p-1 -mt-1 -mr-1">
                         <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>

                  {/* Avatar Selectors */}
                  <div className="flex flex-wrap gap-1.5 items-center mt-2">
                    <button 
                      onClick={() => assignToAll(item.id)}
                      className={`px-2 py-0.5 text-[10px] font-bold rounded border transition-colors ${allSelected ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-gray-50 text-gray-500 border-gray-200 hover:bg-gray-100'}`}
                    >
                      ALL
                    </button>
                    <div className="w-px h-5 bg-gray-200 mx-0.5"></div>
                    {participants.map((p, idx) => {
                      const isSelected = item.assignedTo.includes(p.id);
                      return (
                        <button
                          key={p.id}
                          onClick={() => toggleAssignment(item.id, p.id)}
                          className={`relative w-7 h-7 md:w-8 md:h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all border-2 ${isSelected ? 'border-white shadow-md scale-105' : 'opacity-40 border-transparent grayscale'}`}
                          style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`, color: 'white' }}
                        >
                          {p.name.charAt(0)}
                          {isSelected && (
                             <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-white rounded-full flex items-center justify-center">
                               <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                             </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
               </div>
             );
           })}

           {/* Add Manual Item Row */}
           <div className="flex gap-2 items-center p-3 border border-dashed border-gray-300 rounded-lg bg-gray-50/50 mt-4">
              <input 
                placeholder="添加商品..." 
                className="flex-1 bg-transparent border-none text-sm outline-none"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
              />
              <input 
                type="number" 
                placeholder="0.00" 
                className="w-20 bg-transparent border-b border-gray-300 text-right text-sm outline-none"
                value={newItemPrice}
                onChange={(e) => setNewItemPrice(e.target.value)}
              />
              <button 
                onClick={addItem}
                disabled={!newItemName || !newItemPrice}
                className="bg-gray-800 text-white w-8 h-8 rounded-full flex items-center justify-center text-lg shadow hover:bg-gray-700 disabled:opacity-50 disabled:shadow-none transition-all"
              >
                +
              </button>
           </div>
        </div>

        {/* Footer: Grand Total (Fixed at bottom on mobile via flex layout + z-index) */}
        <div className="shrink-0 p-4 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
           <div className="flex justify-between items-center mb-3">
              <label className="text-sm font-bold text-gray-900">实付总金额:</label>
              <div className="flex items-center gap-2">
                 <span className="font-mono text-indigo-600 font-bold text-xl">¥</span>
                 <input 
                    type="number" 
                    className="text-right font-mono font-bold text-xl text-indigo-600 bg-indigo-50 border border-indigo-100 rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    style={{ width: `${Math.max((grandTotalInput || '').length, 5) + 2}ch` }}
                    value={grandTotalInput}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) => setGrandTotalInput(e.target.value)}
                 />
              </div>
           </div>

           {(parseFloat(grandTotalInput) || itemsTotal) !== itemsTotal && (
              <div className="text-right text-[10px] md:text-xs text-indigo-500 mb-3 font-medium">
                 {(parseFloat(grandTotalInput) || 0) > itemsTotal ? '+' : ''}
                 ¥{( (parseFloat(grandTotalInput) || 0) - itemsTotal ).toFixed(2)} (税费/优惠)
              </div>
           )}

          <button 
            onClick={handleFinish}
            className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-bold text-base rounded-xl shadow-lg shadow-indigo-200 transition-all transform active:scale-[0.98]"
          >
            开始计算 AA
          </button>
        </div>
      </div>
    </div>
  );
};

export interface ReceiptItem {
  id: string;
  name: string;
  price: number;
  assignedTo: string[]; // Array of participant IDs
}

export interface Participant {
  id: string;
  name: string;
  // removed global isPayer, as payer is per-order now, 
  // but we can keep a "default" flag for UI convenience if needed, 
  // though we'll handle it in the Order structure.
}

export interface Order {
  id: string;
  items: ReceiptItem[];
  tax: number;
  payerId: string; // The specific payer for this order
  timestamp: number;
}

export interface BillState {
  orders: Order[];
  participants: Participant[];
}

export enum AppStep {
  UPLOAD = 'UPLOAD',
  EDIT_AND_ASSIGN = 'EDIT_AND_ASSIGN',
  RESULT = 'RESULT',
}

import React, { useState } from 'react';
import { AppStep, BillState, Order, Participant, ReceiptItem } from './types';
import { ReceiptUploader } from './components/ReceiptUploader';
import { EditorView } from './components/EditorView';
import { ResultView } from './components/ResultView';
import { parseReceiptImage } from './services/geminiService';

const DEFAULT_PARTICIPANTS: Participant[] = [
  { id: '1', name: '我' },
  { id: '2', name: '朋友 A' },
  { id: '3', name: '朋友 B' },
  { id: '4', name: '朋友 C' },
];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);

  // Global State
  const [participants, setParticipants] = useState<Participant[]>(DEFAULT_PARTICIPANTS);
  const [orders, setOrders] = useState<Order[]>([]);

  // Temporary state for the order currently being edited/added
  const [currentEditingItems, setCurrentEditingItems] = useState<Partial<ReceiptItem>[]>([]);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);

  const [showAddOrderModal, setShowAddOrderModal] = useState(false);

  // Initial Flow (First Order)
  const handleInitialUpload = async (base64Data: string) => {
    if (!base64Data) {
      startEditingNewOrder([]);
      return;
    }
    setIsProcessing(true);
    try {
      const items = await parseReceiptImage(base64Data);
      startEditingNewOrder(items);
    } catch (error) {
      alert("识别小票失败，请重试或手动输入。");
    } finally {
      setIsProcessing(false);
    }
  };

  const startEditingNewOrder = (items: Partial<ReceiptItem>[]) => {
    setCurrentEditingItems(items);
    setEditingOrderId(null); // null means creating a new order
    setStep(AppStep.EDIT_AND_ASSIGN);
  };

  // Called when Editor finishes (either first order or subsequent orders)
  const handleEditorFinish = (
    items: ReceiptItem[], 
    tax: number, 
    payerId: string, 
    updatedParticipants: Participant[]
  ) => {
    // Update global participants
    setParticipants(updatedParticipants);

    const newOrder: Order = {
      id: editingOrderId || crypto.randomUUID(),
      items,
      tax,
      payerId,
      timestamp: Date.now(),
    };

    if (editingOrderId) {
      // If we were editing an existing order (feature for future), replace it
      setOrders(prev => prev.map(o => o.id === editingOrderId ? newOrder : o));
    } else {
      // Add new order
      setOrders(prev => [...prev, newOrder]);
    }

    setStep(AppStep.RESULT);
  };

  const handleReset = () => {
    const confirm = window.confirm("确定要清空所有订单重新开始吗？");
    if (confirm) {
      setStep(AppStep.UPLOAD);
      setOrders([]);
      setParticipants(DEFAULT_PARTICIPANTS);
      setCurrentEditingItems([]);
      setShowAddOrderModal(false);
    }
  };

  // --- Add Order Logic ---

  const handleAddOrderClick = () => {
    setShowAddOrderModal(true);
  };

  const handleAddOrderSelection = async (mode: 'image' | 'manual') => {
    setShowAddOrderModal(false);

    if (mode === 'manual') {
      startEditingNewOrder([]);
    } else {
      // For image, we need to show uploader, but "inside" the flow
      // We can temporarily switch step to UPLOAD, but we need to know it's for *adding*
      // Easier way: Hide ResultView, show Uploader overlay or reuse UPLOAD step with a flag.
      // Let's reuse the UPLOAD step but change the callback behavior based on context?
      // Simpler: Just set step to UPLOAD. The `orders` state is preserved. 
      // We just need `handleInitialUpload` to distinguish or have a separate handler.
      // Let's create a specific handler for additional uploads.
      setStep(AppStep.UPLOAD); 
      // NOTE: We need a way to tell the main render that we are adding, 
      // but strictly speaking, if `orders.length > 0`, we are adding.
    }
  };

  // Wrapper for upload to decide if it's initial or additional
  const handleImageSelectedWrapper = async (base64: string) => {
    if (!base64) {
       // Manual
       startEditingNewOrder([]);
       return;
    }

    setIsProcessing(true);
    try {
      const items = await parseReceiptImage(base64);
      startEditingNewOrder(items);
    } catch (error) {
       alert("识别失败");
    } finally {
      setIsProcessing(false);
    }
  };


  return (
    <div className="fixed inset-0 bg-gray-50 text-gray-800 font-sans flex flex-col overflow-hidden">

      <header className="px-4 py-3 md:p-6 bg-white shadow-sm shrink-0 z-20 relative">
        <div className="max-w-7xl mx-auto flex items-center gap-3">
          <div className="w-8 h-8 md:w-10 md:h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg">
            AA
          </div>
          <h1 className="text-lg md:text-xl font-bold tracking-tight text-gray-900">AA Pay</h1>
          {orders.length > 0 && step === AppStep.RESULT && (
            <span className="ml-2 px-2 py-0.5 bg-gray-100 text-gray-500 text-xs rounded-full">
              {orders.length} 单
            </span>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative w-full max-w-5xl mx-auto md:p-6">

        {step === AppStep.UPLOAD && (
          <div className="w-full h-full overflow-y-auto p-4 animate-fade-in-up">
            <div className="text-center mb-6 md:mb-10 mt-4 md:mt-10">
              <h2 className="text-2xl md:text-4xl font-extrabold text-gray-900 mb-2 md:mb-4">
                {orders.length > 0 ? "添加新订单" : "轻松搞定聚餐算账"}
              </h2>
              <p className="text-sm md:text-lg text-gray-600 max-w-2xl mx-auto">
                {orders.length > 0 ? "请上传下一张小票，或选择手动输入" : "上传小票截图或照片，AI 自动识别菜品，简单勾选谁吃了什么。"}
              </p>
            </div>

            <ReceiptUploader 
              onImageSelected={handleImageSelectedWrapper} 
              isProcessing={isProcessing} 
            />

            {orders.length > 0 && (
               <div className="mt-8 text-center">
                 <button onClick={() => setStep(AppStep.RESULT)} className="text-gray-500 underline">
                   返回计算结果
                 </button>
               </div>
            )}
          </div>
        )}

        {step === AppStep.EDIT_AND_ASSIGN && (
          <div className="w-full h-full animate-fade-in">
             <EditorView 
                initialItems={currentEditingItems}
                // Pass current global participants so user can select from them
                currentParticipants={participants}
                onFinish={handleEditorFinish}
                isFirstOrder={orders.length === 0}
             />
          </div>
        )}

        {step === AppStep.RESULT && (
          <div className="w-full h-full animate-fade-in">
            <ResultView 
              state={{ orders, participants }}
              onReset={handleReset} 
              onAddOrder={handleAddOrderClick}
            />
          </div>
        )}

      </main>

      {/* Add Order Selection Modal */}
      {showAddOrderModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-2xl scale-100 animate-scale-in">
