                 <span className="font-bold">上传小票图片</span>
               </button>
               <button 
                 onClick={() => handleAddOrderSelection('manual')}
                 className="w-full py-4 flex flex-col items-center justify-center bg-white hover:bg-gray-50 border-2 border-gray-200 text-gray-700 rounded-xl transition-all"
               >
                 <svg className="w-8 h-8 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                 <span className="font-bold">手动输入</span>
               </button>
             </div>
             <button 
               onClick={() => setShowAddOrderModal(false)}
               className="mt-6 w-full py-2 text-gray-400 hover:text-gray-600 text-sm font-medium"
             >
               取消
             </button>
