        </div>
      )}

      {/* Hidden input for the modal to trigger file selection reusing the uploader logic logic slightly hacky but effective for this structure */}
      <div className="hidden">
        <ReceiptUploader onImageSelected={onUploadHandler} isProcessing={isProcessing} id="hidden-upload-trigger" />
      </div>

    </div>
  );
};

