import React, { useRef, useState, useEffect } from 'react';
import { Spinner } from './Spinner';

interface ReceiptUploaderProps {
  onImageSelected: (base64: string) => Promise<void>;
  isProcessing: boolean;
  id?: string; // Optional ID to trigger from outside
}

export const ReceiptUploader: React.FC<ReceiptUploaderProps> = ({ onImageSelected, isProcessing, id }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragActive, setDragActive] = useState(false);

  // Allow external trigger if ID is provided
  useEffect(() => {
    if (id) {
        const trigger = document.getElementById(id);
        if (trigger) {
            trigger.onclick = () => fileInputRef.current?.click();
        }
    }
  }, [id]);

  const handleFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
      alert('请上传图片文件');
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      const base64Data = base64.split(',')[1]; 
      await onImageSelected(base64Data);
    };
    reader.readAsDataURL(file);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(true);
  };

  const onDragLeave = () => {
    setDragActive(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  return (
    <div className={`w-full max-w-lg mx-auto text-center ${id ? '' : ''}`}> 
      {/* If used as hidden trigger, we only render the input */}
      <input 
          type="file" 
          ref={fileInputRef}
          className="hidden" 
          accept="image/*"
          onChange={(e) => e.target.files && handleFile(e.target.files[0])}
      />

      {!id && (
        <>
            <div 
                className={`
                relative border-2 border-dashed rounded-2xl p-10 transition-all duration-300
                ${dragActive ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 bg-white'}
                ${isProcessing ? 'opacity-80 pointer-events-none' : 'hover:border-indigo-400'}
                `}
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={onDrop}
            >

                {isProcessing ? (
                <div className="flex flex-col items-center justify-center py-8">
                    <div className="bg-indigo-600 p-3 rounded-full mb-4 shadow-lg shadow-indigo-200">
                    <Spinner />
                    </div>
                    <h3 className="text-xl font-bold text-gray-800">正在分析小票...</h3>
                    <p className="text-gray-500 mt-2">AI 正在努力识别菜品和价格</p>
                </div>
                ) : (
                <div className="flex flex-col items-center py-4">
                    <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center mb-4 text-indigo-600">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    </div>
                    <h3 className="text-lg font-bold text-gray-800 mb-2">上传小票</h3>
                    <p className="text-gray-500 text-sm mb-6 max-w-xs">将小票图片拖拽至此，或点击选择</p>
                    <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="bg-gray-900 text-white px-6 py-3 rounded-lg font-semibold shadow-lg hover:bg-gray-800 transition transform active:scale-95"
                    >
                    选择图片
                    </button>
                </div>
                )}
            </div>

            {!isProcessing && (
                <button 
                onClick={() => onImageSelected('')} // Pass empty to skip AI
                className="mt-6 text-indigo-600 font-medium text-sm hover:underline"
                >
                跳过，手动输入
                </button>
            )}
        </>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Participant, ReceiptItem } from '../types';

interface EditorViewProps {
  initialItems: Partial<ReceiptItem>[];
  currentParticipants: Participant[];
  onFinish: (items: ReceiptItem[], tax: number, payerId: string, participants: Participant[]) => void;
  isFirstOrder: boolean;
}

export const EditorView: React.FC<EditorViewProps> = ({ initialItems, currentParticipants, onFinish, isFirstOrder }) => {
  // Local state for participants to allow adding/renaming within this view
  const [participants, setParticipants] = useState<Participant[]>(currentParticipants);

  // Payer state for THIS order
  const [selectedPayerId, setSelectedPayerId] = useState<string>(
     currentParticipants[0]?.id || '1'
  );

  const [items, setItems] = useState<ReceiptItem[]>(() => {
    return initialItems.map(i => ({ 
      id: i.id || crypto.randomUUID(), 
      name: i.name || '未知商品', 
      price: i.price || 0, 
      assignedTo: participants.map(p => p.id) 
    }));
  });

  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');

  const itemsTotal = items.reduce((sum, i) => sum + i.price, 0);

  const [grandTotalInput, setGrandTotalInput] = useState<string>('');

  useEffect(() => {
    // Auto-fill grand total if empty and items exist
    if (grandTotalInput === '' && itemsTotal > 0) {
      setGrandTotalInput(itemsTotal.toFixed(2));
    }
  }, [itemsTotal]);

  const [editingPayer, setEditingPayer] = useState(false);
  const [isPeopleExpanded, setIsPeopleExpanded] = useState(false);

  const toggleAssignment = (itemId: string, participantId: string) => {
    setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const isAssigned = item.assignedTo.includes(participantId);
      const newAssignedTo = isAssigned 
        ? item.assignedTo.filter(id => id !== participantId) 
        : [...item.assignedTo, participantId];
      return { ...item, assignedTo: newAssignedTo };
    }));
  };

  const assignToAll = (itemId: string) => {
     setItems(prev => prev.map(item => {
      if (item.id !== itemId) return item;
      const allSelected = participants.every(p => item.assignedTo.includes(p.id));
      return { ...item, assignedTo: allSelected ? [] : participants.map(p => p.id) };
     }));
  };

  const addItem = () => {
    if (!newItemName || !newItemPrice) return;
    setItems([...items, {
      id: crypto.randomUUID(),
      name: newItemName,
      price: parseFloat(newItemPrice),
      assignedTo: participants.map(p => p.id)
    }]);
    setNewItemName('');
    setNewItemPrice('');
  };

  const deleteItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const updateParticipantName = (id: string, name: string) => {
    setParticipants(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const addParticipant = () => {
    const newId = crypto.randomUUID();
    setParticipants([...participants, { id: newId, name: `朋友 ${participants.length}` }]);
  };

  const handleFinish = () => {
    const finalGrandTotal = parseFloat(grandTotalInput) || itemsTotal;
    const taxAndTip = finalGrandTotal - itemsTotal;
    onFinish(items, taxAndTip, selectedPayerId, participants);
  };

  const currentPayerName = participants.find(p => p.id === selectedPayerId)?.name || '未选择';

  return (
    <div className="w-full h-full flex flex-col md:flex-row gap-4 md:bg-transparent bg-gray-50">

      {/* Left Column: People */}
      <div className={`
        bg-white shadow-sm md:shadow-md md:rounded-xl shrink-0 
        flex flex-col md:w-1/3 transition-all duration-300 z-10
        ${isPeopleExpanded ? 'max-h-[60vh]' : 'max-h-[30vh]'} md:max-h-full md:h-full
      `}>
        {/* Mobile Toggle Handle */}
        <div 
          className="md:hidden flex justify-center pt-2 pb-1 cursor-pointer bg-gray-50 border-b border-gray-200"
          onClick={() => setIsPeopleExpanded(!isPeopleExpanded)}
        >
           <div className="w-10 h-1 bg-gray-300 rounded-full"></div>
        </div>

        <div className="p-4 overflow-y-auto">
          {/* Payer Section - Distinct for this order */}
          <div className="mb-4">
             <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-2">
                {isFirstOrder ? '谁付的款 (本次)' : '本次订单付款人'}
             </h3>
             {editingPayer ? (
                <div className="space-y-1">
                  {participants.map(p => (
                    <button 
                     key={p.id}
                     onClick={() => { setSelectedPayerId(p.id); setEditingPayer(false); }}
                     className={`w-full text-left px-3 py-2 rounded text-sm ${p.id === selectedPayerId ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}
                    >
                      {p.name}
                    </button>
                  ))}
                </div>
             ) : (
                <div className="flex justify-between items-center bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100 cursor-pointer" onClick={() => setEditingPayer(true)}>
                  <div className="flex items-center gap-2">
                     <span className="text-xs text-indigo-400">当前:</span>
                     <span className="font-bold text-indigo-900 text-sm">{currentPayerName}</span>
                  </div>
                  <span className="text-xs text-indigo-500 font-medium">更改</span>
                </div>
             )}
          </div>

          {/* Participants List */}
          <div>
            <div className="flex justify-between items-center mb-2">
               <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide">参与者 ({participants.length})</h3>
            </div>
            <div className="space-y-2">
              {participants.map((p, idx) => (
                <div key={p.id} className="flex items-center gap-2 bg-gray-50/50 p-1.5 rounded-lg border border-transparent hover:border-gray-200 focus-within:border-indigo-300 transition-colors">
                  <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0 shadow-sm`} style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`}}>
                    {p.name.charAt(0)}
                  </div>
                  <input 
                    type="text" 
                    value={p.name}
                    onChange={(e) => updateParticipantName(p.id, e.target.value)}
                    className="flex-1 bg-transparent border-none outline-none text-gray-800 text-sm p-0 focus:ring-0"
                    placeholder="Name"
                  />
                </div>
              ))}
               <button 
                  onClick={addParticipant}
                  className="w-full mt-1 py-1.5 text-xs text-indigo-600 border border-dashed border-indigo-300 rounded hover:bg-indigo-50 transition"
               >
                 + 添加人员
               </button>
            </div>
          </div>
        </div>
      </div>

      {/* Right Column: Items */}
      <div className="flex-1 bg-white md:rounded-xl shadow-sm md:shadow-md flex flex-col min-h-0 overflow-hidden relative">
        <div className="px-4 py-3 border-b border-gray-100 bg-white shrink-0 flex justify-between items-center z-10">
          <div>
            <h2 className="font-bold text-gray-800 text-sm md:text-base">
                {isFirstOrder ? '订单详情' : '新增订单详情'}
            </h2>
            <p className="text-[10px] md:text-xs text-gray-500">点击下方头像分配</p>
          </div>
          <div className="text-right">
             <span className="text-xs text-gray-500 mr-2">小计:</span>
             <span className="font-mono font-bold text-base md:text-lg text-gray-700">¥{itemsTotal.toFixed(2)}</span>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-3 md:p-4 space-y-3 pb-24 md:pb-4">
           {items.map((item) => {
             const allSelected = participants.every(p => item.assignedTo.includes(p.id));

             return (
               <div key={item.id} className="bg-white border border-gray-100 rounded-lg p-3 shadow-sm">
                  <div className="flex justify-between items-start mb-2 gap-2">
                    <div className="flex-1 min-w-0">
                      <input 
                        className="font-medium text-gray-800 w-full outline-none focus:text-indigo-600 text-sm md:text-base bg-transparent truncate"
                        value={item.name}
                        onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, name: e.target.value} : i))}
                        placeholder="商品名称"
                      />
                      <div className="text-[10px] md:text-xs text-gray-400 mt-0.5 truncate">
                        {item.assignedTo.length === 0 ? '未分配' : 
                         allSelected ? '所有人' : 
                         participants.filter(p => item.assignedTo.includes(p.id)).map(p => p.name).join(', ')}
                      </div>
                    </div>
                    <div className="flex items-center gap-1 shrink-0">
                       <span className="font-mono text-gray-400 text-xs">¥</span>
                       <input 
                         type="number"
                         className="w-16 text-right font-mono font-bold text-gray-800 border-b border-gray-200 focus:border-indigo-500 outline-none text-sm md:text-base p-0"
                         value={item.price}
                         onFocus={(e) => e.target.select()}
                         onChange={(e) => setItems(prev => prev.map(i => i.id === item.id ? {...i, price: parseFloat(e.target.value) || 0} : i))}
                       />
                    </div>
                    <button onClick={() => deleteItem(item.id)} className="text-gray-300 hover:text-red-500 p-1 -mt-1 -mr-1">
                         <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
