                          style={{ backgroundColor: `hsl(${idx * 60}, 70%, 50%)`, color: 'white' }}
                        >
                          {p.name.charAt(0)}
                          {isSelected && (
                             <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-white rounded-full flex items-center justify-center">
                               <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                             </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
               </div>
             );
           })}

           {/* Add Manual Item Row */}
           <div className="flex gap-2 items-center p-3 border border-dashed border-gray-300 rounded-lg bg-gray-50/50 mt-4">
              <input 
                placeholder="添加商品..." 
                className="flex-1 bg-transparent border-none text-sm outline-none"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
              />
              <input 
                type="number" 
                placeholder="0.00" 
                className="w-20 bg-transparent border-b border-gray-300 text-right text-sm outline-none"
                value={newItemPrice}
                onChange={(e) => setNewItemPrice(e.target.value)}
              />
              <button 
                onClick={addItem}
                disabled={!newItemName || !newItemPrice}
                className="bg-gray-800 text-white w-8 h-8 rounded-full flex items-center justify-center text-lg shadow hover:bg-gray-700 disabled:opacity-50 disabled:shadow-none transition-all"
              >
                +
              </button>
           </div>
        </div>

        {/* Footer: Grand Total */}
        <div className="shrink-0 p-4 bg-white border-t border-gray-200 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
           <div className="flex justify-between items-center mb-3">
              <label className="text-sm font-bold text-gray-900">
                {isFirstOrder ? '实付总金额:' : '本单实付金额:'}
              </label>
              <div className="flex items-center gap-2">
                 <span className="font-mono text-indigo-600 font-bold text-xl">¥</span>
                 <input 
                    type="number" 
                    className="text-right font-mono font-bold text-xl text-indigo-600 bg-indigo-50 border border-indigo-100 rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                    style={{ width: `${Math.max((grandTotalInput || '').length, 5) + 2}ch` }}
                    value={grandTotalInput}
                    onFocus={(e) => e.target.select()}
                    onChange={(e) => setGrandTotalInput(e.target.value)}
                 />
              </div>
           </div>

           {(parseFloat(grandTotalInput) || itemsTotal) !== itemsTotal && (
              <div className="text-right text-[10px] md:text-xs text-indigo-500 mb-3 font-medium">
                 {(parseFloat(grandTotalInput) || 0) > itemsTotal ? '+' : ''}
                 ¥{( (parseFloat(grandTotalInput) || 0) - itemsTotal ).toFixed(2)} (税费/优惠)
              </div>
           )}

          <button 
            onClick={handleFinish}
            className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-bold text-base rounded-xl shadow-lg shadow-indigo-200 transition-all transform active:scale-[0.98]"
          >
            {isFirstOrder ? '开始计算 AA' : '确认添加并计算'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { BillState } from '../types';

interface ResultViewProps {
  state: BillState;
  onReset: () => void;
  onAddOrder: () => void;
}

export const ResultView: React.FC<ResultViewProps> = ({ state, onReset, onAddOrder }) => {
  const { orders, participants } = state;

  // 1. Calculate Total Bill (Sum of all orders)
  const totalBill = orders.reduce((total, order) => {
    const orderItemsTotal = order.items.reduce((s, i) => s + i.price, 0);
    return total + orderItemsTotal + order.tax;
  }, 0);

  // 2. Calculate Net Balances by aggregating all orders
  // Positive = Is owed money (Receiver)
  // Negative = Owes money (Payer)
  const netBalances: Record<string, number> = {};
  participants.forEach(p => netBalances[p.id] = 0);

  orders.forEach(order => {
    const orderItemsTotal = order.items.reduce((s, i) => s + i.price, 0);
    const orderFinalTotal = orderItemsTotal + order.tax;

    // Calculate consumption per person for THIS order
    const consumption: Record<string, number> = {};
    participants.forEach(p => consumption[p.id] = 0);

    order.items.forEach(item => {
      if (item.assignedTo.length > 0) {
        const splitPrice = item.price / item.assignedTo.length;
        item.assignedTo.forEach(pid => {
          if (consumption[pid] !== undefined) consumption[pid] += splitPrice;
        });
      } else {
        // If unassigned, split among all participants
        const splitPrice = item.price / participants.length;
        participants.forEach(p => consumption[p.id] += splitPrice);
      }
    });

    // Determine the ratio to distribute tax/tip
    // If orderItemsTotal is 0 (e.g. manual entry of total only), we split everything evenly or by headcount
    const ratio = orderItemsTotal > 0 ? (orderFinalTotal / orderItemsTotal) : (orderFinalTotal / participants.length);

    participants.forEach(p => {
      // Calculate what they should have paid for this order (including tax share)
      const shouldPay = orderItemsTotal > 0 ? (consumption[p.id] * ratio) : (orderFinalTotal / participants.length);

      // Update Net Balance:
      // Subtract what they "consumed" (debt)
      netBalances[p.id] -= shouldPay;

      // Add what they "paid" (credit) if they are the payer
      if (p.id === order.payerId) {
        netBalances[p.id] += orderFinalTotal;
      }
    });
  });

  return (
    <div className="w-full h-full md:h-[85vh] max-w-2xl mx-auto bg-white md:rounded-xl shadow-lg overflow-hidden flex flex-col md:border border-gray-100">

      {/* Header Result Card */}
      <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 md:p-8 text-white shrink-0 shadow-md z-10 relative overflow-hidden">
        {/* Decorative elements */}
        <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-5 rounded-full -mr-10 -mt-10 pointer-events-none"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-start mb-4">
             <h2 className="text-xl md:text-2xl font-bold opacity-90">总账单结果</h2>
             <div className="bg-white/10 px-3 py-1 rounded-full text-xs font-medium border border-white/20">
               共 {orders.length} 笔订单
             </div>
          </div>

          <div>
              <p className="text-indigo-200 text-xs md:text-sm uppercase tracking-wider mb-1">所有订单总额</p>
              <div className="flex items-baseline gap-1">
                  <span className="text-2xl">¥</span>
                  <span className="font-mono font-bold text-4xl md:text-5xl">{totalBill.toFixed(2)}</span>
              </div>
          </div>
        </div>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 bg-gray-50">

        {/* Person Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
           {participants.map(person => {
             const balance = netBalances[person.id];
             const isReceiver = balance > 0.01; 
             const isPayer = balance < -0.01; 
             const isSettled = Math.abs(balance) <= 0.01;

             return (
               <div key={person.id} className={`rounded-xl p-4 relative shadow-sm transition-all border ${isReceiver ? 'bg-white border-green-200 ring-1 ring-green-50' : isSettled ? 'bg-gray-50 border-gray-200 opacity-70' : 'bg-white border-red-100'}`}>
                  <div className="flex justify-between items-center mb-3">
                    <div className="flex items-center gap-2">
                        <div className={`w-2 h-8 rounded-full ${isReceiver ? 'bg-green-500' : isPayer ? 'bg-red-500' : 'bg-gray-300'}`}></div>
                        <h3 className="font-bold text-base text-gray-800">{person.name}</h3>
                    </div>
                    {isReceiver && <span className="bg-green-100 text-green-700 text-[10px] font-bold px-2 py-0.5 rounded-full">收款方</span>}
                  </div>

                  <div className="flex justify-between items-end">
                      <div className="text-right w-full">
                        <p className="text-xs font-medium text-gray-400 mb-0.5">
                            {isReceiver ? '应收回' : isPayer ? '需支付' : '已结清'}
                        </p>
                        <p className={`font-mono font-bold text-xl ${isReceiver ? 'text-green-600' : isPayer ? 'text-red-500' : 'text-gray-400'}`}>
                            {isSettled ? '¥0.00' : `¥${Math.abs(balance).toFixed(2)}`}
                        </p>
                      </div>
                  </div>
               </div>
             );
           })}
        </div>

        {/* Transfer Scheme */}
        <div className="bg-white rounded-xl p-5 border border-gray-200 shadow-sm">
          <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2 text-sm uppercase tracking-wide">
            <svg className="w-4 h-4 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
            最优转账方案
          </h3>
          <ul className="space-y-3">
             {(() => {
                const debtors = participants.filter(p => netBalances[p.id] < -0.01).map(p => ({ id: p.id, name: p.name, amount: -netBalances[p.id] }));
                const creditors = participants.filter(p => netBalances[p.id] > 0.01).map(p => ({ id: p.id, name: p.name, amount: netBalances[p.id] }));

                // Sort to optimize number of transactions
                debtors.sort((a,b) => b.amount - a.amount);
                creditors.sort((a,b) => b.amount - a.amount);

                const transfers = [];
                let i = 0; 
                let j = 0;

                while(i < debtors.length && j < creditors.length) {
                    const debtor = debtors[i];
                    const creditor = creditors[j];

                    const amount = Math.min(debtor.amount, creditor.amount);
                    if (amount > 0.01) {
                        transfers.push({ from: debtor.name, to: creditor.name, amount });
                    }

                    debtor.amount -= amount;
                    creditor.amount -= amount;

                    if (debtor.amount < 0.01) i++;
                    if (creditor.amount < 0.01) j++;
                }

                if (transfers.length === 0) {
                    return <li className="text-gray-400 text-sm text-center py-2">无需转账，帐平了！</li>
                }

                return transfers.map((t, idx) => (
                    <li key={idx} className="flex items-center justify-between border-b border-gray-50 pb-2 last:border-0 last:pb-0">
                        <div className="flex items-center gap-2 text-sm">
                            <span className="font-bold text-gray-800">{t.from}</span>
                            <span className="text-gray-400 text-xs">支付给</span>
                            <span className="font-bold text-gray-800">{t.to}</span>
                        </div>
                        <span className="font-mono font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded text-sm">¥{t.amount.toFixed(2)}</span>
                    </li>
                ));
             })()}
          </ul>
        </div>
      </div>

      {/* Footer Actions */}
      <div className="p-4 bg-white border-t border-gray-100 flex flex-col gap-3 shrink-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
         <button 
          onClick={onAddOrder}
          className="w-full py-3 px-4 bg-gray-900 text-white font-semibold rounded-xl hover:bg-gray-800 active:bg-black transition shadow-md flex items-center justify-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          新增一笔订单 (由他人付款)
        </button>
        <button 
          onClick={onReset}
          className="w-full py-3 px-4 bg-white border border-gray-200 text-red-500 font-semibold rounded-xl hover:bg-red-50 active:bg-red-100 transition shadow-sm text-sm"
        >
          清空所有数据重新开始
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { AppStep, Order, Participant, ReceiptItem } from './types';
import { ReceiptUploader } from './components/ReceiptUploader';
import { EditorView } from './components/EditorView';
import { ResultView } from './components/ResultView';
import { parseReceiptImage } from './services/geminiService';

const DEFAULT_PARTICIPANTS: Participant[] = [
  { id: '1', name: '我' },
  { id: '2', name: '朋友 A' },
  { id: '3', name: '朋友 B' },
  { id: '4', name: '朋友 C' },
];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);

  // Global State
  const [participants, setParticipants] = useState<Participant[]>(DEFAULT_PARTICIPANTS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeOrderId, setActiveOrderId] = useState<string | null>(null);

  // Modal State
  const [showAddOrderModal, setShowAddOrderModal] = useState(false);

  // --- Initial Upload ---
  const handleInitialUpload = async (base64Data: string) => {
    await createNewOrder(base64Data);
    setStep(AppStep.EDIT_AND_ASSIGN);
  };

  // --- Core Logic ---

  const createNewOrder = async (base64Data: string) => {
    let newItems: Partial<ReceiptItem>[] = [];

    if (base64Data) {
      setIsProcessing(true);
      try {
        newItems = await parseReceiptImage(base64Data);
      } catch (error) {
        alert("识别小票失败，转为手动输入。");
      } finally {
        setIsProcessing(false);
      }
    }

    const newOrder: Order = {
      id: crypto.randomUUID(),
      // Ensure items have full structure
      items: newItems.map(i => ({
        id: i.id || crypto.randomUUID(),
        name: i.name || '新商品',
        price: i.price || 0,
        assignedTo: participants.map(p => p.id) // Default assign to all
      })) as ReceiptItem[],
      tax: 0,
      payerId: participants[0]?.id || '1', // Default payer
      timestamp: Date.now(),
    };

    setOrders(prev => [...prev, newOrder]);
    setActiveOrderId(newOrder.id);
  };

  const handleUpdateOrder = (updatedOrder: Order) => {
    setOrders(prev => prev.map(o => o.id === updatedOrder.id ? updatedOrder : o));
  };

  const handleDeleteOrder = (orderId: string) => {
    if (orders.length <= 1) {
      if (window.confirm("这是最后一笔订单，删除将清空并返回首页，确定吗？")) {
         handleReset();
      }
      return;
    }
    const newOrders = orders.filter(o => o.id !== orderId);
    setOrders(newOrders);
    if (activeOrderId === orderId) {
      setActiveOrderId(newOrders[0].id);
    }
  };

  const handleAddOrderRequest = () => {
    setShowAddOrderModal(true);
  };

  const handleAddOrderConfirm = async (base64: string) => {
    setShowAddOrderModal(false);
    await createNewOrder(base64);
  };

  const handleReset = () => {
    setStep(AppStep.UPLOAD);
    setOrders([]);
    setParticipants(DEFAULT_PARTICIPANTS);
    setActiveOrderId(null);
  };

  const handleViewResults = () => {
     setStep(AppStep.RESULT);
  };

  return (
    <div className="fixed inset-0 bg-gray-50 text-gray-800 font-sans flex flex-col overflow-hidden">

      {/* Header */}
      <header className="px-4 py-3 md:p-6 bg-white shadow-sm shrink-0 z-20 relative">
        <div className="max-w-7xl mx-auto flex items-center gap-3">
          <div className="w-8 h-8 md:w-10 md:h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg">
            AA
          </div>
          <h1 className="text-lg md:text-xl font-bold tracking-tight text-gray-900">AA Pay</h1>
          {orders.length > 0 && (
            <span className="ml-2 px-2 py-0.5 bg-gray-100 text-gray-500 text-xs rounded-full border border-gray-200">
              {orders.length} 笔订单
            </span>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative w-full max-w-6xl mx-auto md:p-6">

        {step === AppStep.UPLOAD && (
          <div className="w-full h-full overflow-y-auto p-4 animate-fade-in-up">
            <div className="text-center mb-6 md:mb-10 mt-4 md:mt-10">
              <h2 className="text-2xl md:text-4xl font-extrabold text-gray-900 mb-2 md:mb-4">轻松搞定聚餐算账</h2>
              <p className="text-sm md:text-lg text-gray-600 max-w-2xl mx-auto">
                上传小票截图或照片，AI 自动识别菜品，支持多人多订单合并计算。
              </p>
            </div>
            <ReceiptUploader onImageSelected={handleInitialUpload} isProcessing={isProcessing} />
          </div>
        )}

        {step === AppStep.EDIT_AND_ASSIGN && activeOrderId && (
          <div className="w-full h-full animate-fade-in">
             <EditorView 
                orders={orders}
                activeOrderId={activeOrderId}
                participants={participants}
                onUpdateParticipants={setParticipants}
                onUpdateOrder={handleUpdateOrder}
                onSelectOrder={setActiveOrderId}
                onAddOrder={handleAddOrderRequest}
                onDeleteOrder={handleDeleteOrder}
                onViewResult={handleViewResults}
             />
          </div>
        )}

        {step === AppStep.RESULT && (
          <div className="w-full h-full animate-fade-in">
            <ResultView 
              state={{ orders, participants }} 
              onReset={handleReset} 
              onBackToEdit={() => setStep(AppStep.EDIT_AND_ASSIGN)}
            />
          </div>
        )}

      </main>

      {/* Add Order Modal */}
      {showAddOrderModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-2xl scale-100 animate-scale-in">
             <h3 className="text-xl font-bold text-gray-900 mb-6 text-center">添加新订单</h3>
             <div className="space-y-3">
               <button 
                 onClick={() => { document.getElementById('hidden-upload-trigger')?.click(); }}
                 className="w-full py-4 flex flex-col items-center justify-center bg-indigo-50 hover:bg-indigo-100 border-2 border-indigo-100 text-indigo-700 rounded-xl transition-all group"
               >
                 <svg className="w-8 h-8 mb-2 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                 <span className="font-bold">上传小票图片</span>
               </button>
               <button 
                 onClick={() => handleAddOrderConfirm('')}
                 className="w-full py-4 flex flex-col items-center justify-center bg-white hover:bg-gray-50 border-2 border-gray-200 text-gray-700 rounded-xl transition-all group"
               >
                 <svg className="w-8 h-8 mb-2 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                 <span className="font-bold">手动输入</span>
               </button>
             </div>
             <button 
               onClick={() => setShowAddOrderModal(false)}
               className="mt-6 w-full py-2 text-gray-400 hover:text-gray-600 text-sm font-medium"
             >
               取消
             </button>
          </div>
        </div>
      )}

      {/* Hidden input for the modal to trigger file selection */}
      <div className="hidden">
        <ReceiptUploader onImageSelected={handleAddOrderConfirm} isProcessing={isProcessing} id="hidden-upload-trigger" />
      </div>

    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Order, Participant, ReceiptItem } from '../types';

interface EditorViewProps {
  orders: Order[];
  activeOrderId: string;
  participants: Participant[];
  onUpdateParticipants: (participants: Participant[]) => void;
  onUpdateOrder: (order: Order) => void;
  onSelectOrder: (id: string) => void;
  onAddOrder: () => void;
  onDeleteOrder: (id: string) => void;
  onViewResult: () => void;
}

export const EditorView: React.FC<EditorViewProps> = ({ 
  orders, 
  activeOrderId, 
  participants, 
  onUpdateParticipants, 
  onUpdateOrder, 
  onSelectOrder,
  onAddOrder,
  onDeleteOrder,
  onViewResult
}) => {
  const currentOrder = orders.find(o => o.id === activeOrderId);

  if (!currentOrder) return null;

  // Local state for new item inputs
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');

  // Calculate items total
  const itemsTotal = currentOrder.items.reduce((sum, i) => sum + i.price, 0);

  // Grand Total Input State
  const [grandTotalInput, setGrandTotalInput] = useState<string>('');

  // Sync grand total input when order changes or items change significantly if not set
  useEffect(() => {
    const calculatedTotal = itemsTotal + currentOrder.tax;
    if (Math.abs(calculatedTotal - (parseFloat(grandTotalInput) || 0)) > 0.01) {
        // Only update if current input is empty or we just switched orders
        // Ideally we want to persist user input per order, but for now we re-derive from tax if possible
        // Better: let's calculate what the input SHOULD be based on state
        setGrandTotalInput((itemsTotal + currentOrder.tax).toFixed(2));
    }
  }, [activeOrderId, itemsTotal, currentOrder.tax]);


  const [editingPayer, setEditingPayer] = useState(false);
  const [isSidebarExpanded, setIsSidebarExpanded] = useState(false);

  // --- Handlers ---

  const handleUpdateGrandTotal = (val: string) => {
      setGrandTotalInput(val);
      const newTotal = parseFloat(val) || 0;
      // Tax = Total - ItemsSum
      const newTax = newTotal - itemsTotal;
      onUpdateOrder({ ...currentOrder, tax: newTax });
  };

  const toggleAssignment = (itemId: string, participantId: string) => {
    const newItems = currentOrder.items.map(item => {
      if (item.id !== itemId) return item;
      const isAssigned = item.assignedTo.includes(participantId);
      const newAssignedTo = isAssigned 
        ? item.assignedTo.filter(id => id !== participantId) 
        : [...item.assignedTo, participantId];
      return { ...item, assignedTo: newAssignedTo };
    });
    onUpdateOrder({ ...currentOrder, items: newItems });
  };

  const assignToAll = (itemId: string) => {
     const newItems = currentOrder.items.map(item => {
      if (item.id !== itemId) return item;
      const allSelected = participants.every(p => item.assignedTo.includes(p.id));
      return { ...item, assignedTo: allSelected ? [] : participants.map(p => p.id) };
     });
     onUpdateOrder({ ...currentOrder, items: newItems });
  };

  const addItem = () => {
    if (!newItemName || !newItemPrice) return;
    const newItem: ReceiptItem = {
      id: crypto.randomUUID(),
      name: newItemName,
      price: parseFloat(newItemPrice),
      assignedTo: participants.map(p => p.id)
    };
    onUpdateOrder({ ...currentOrder, items: [...currentOrder.items, newItem] });
    setNewItemName('');
    setNewItemPrice('');
  };

  const deleteItem = (id: string) => {
    onUpdateOrder({ ...currentOrder, items: currentOrder.items.filter(i => i.id !== id) });
  };

  const updateParticipantName = (id: string, name: string) => {
    onUpdateParticipants(participants.map(p => p.id === id ? { ...p, name } : p));
  };

  const addParticipant = () => {
    const newId = crypto.randomUUID();
    onUpdateParticipants([...participants, { id: newId, name: `朋友 ${participants.length}` }]);
  };

  const handlePayerChange = (payerId: string) => {
    onUpdateOrder({ ...currentOrder, payerId });
    setEditingPayer(false);
  };

  const currentPayerName = participants.find(p => p.id === currentOrder.payerId)?.name || '未选择';

  return (
    <div className="w-full h-full flex flex-col md:flex-row gap-4 md:bg-transparent bg-gray-50">

      {/* Left Column: Sidebar (Payer, Orders, People) */}
      <div className={`
        bg-white shadow-sm md:shadow-md md:rounded-xl shrink-0 
        flex flex-col md:w-1/3 transition-all duration-300 z-10
        ${isSidebarExpanded ? 'max-h-[70vh]' : 'max-h-[30vh]'} md:max-h-full md:h-full
      `}>
        {/* Mobile Toggle Handle */}
        <div 
          className="md:hidden flex justify-center pt-2 pb-1 cursor-pointer bg-gray-50 border-b border-gray-200"
          onClick={() => setIsSidebarExpanded(!isSidebarExpanded)}
        >
           <div className="w-10 h-1 bg-gray-300 rounded-full"></div>
        </div>

        <div className="p-4 overflow-y-auto flex-1 flex flex-col gap-6">

          {/* 1. Who Paid (For THIS Order) */}
          <div>
             <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-2">
                谁付的款 (本单)
             </h3>
             {editingPayer ? (
                <div className="space-y-1">
                  {participants.map(p => (
                    <button 
                     key={p.id}
                     onClick={() => handlePayerChange(p.id)}
                     className={`w-full text-left px-3 py-2 rounded text-sm ${p.id === currentOrder.payerId ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}
                    >
                      {p.name}
                    </button>
                  ))}
                </div>
             ) : (
                <div className="flex justify-between items-center bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100 cursor-pointer" onClick={() => setEditingPayer(true)}>
                  <div className="flex items-center gap-2">
                     <span className="text-xs text-indigo-400">当前:</span>
                     <span className="font-bold text-indigo-900 text-sm">{currentPayerName}</span>
                  </div>
                  <span className="text-xs text-indigo-500 font-medium">更改</span>
                </div>
             )}
          </div>

          {/* 2. Order List (The requested "Below Who Paid" feature) */}
          <div className="border-t border-gray-100 pt-4">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wide mb-2">订单列表</h3>
            <div className="space-y-2">
                {orders.map((order, idx) => (
                    <div 
                        key={order.id} 
                        onClick={() => onSelectOrder(order.id)}
                        className={`group flex items-center justify-between p-2 rounded-lg border cursor-pointer transition-all ${order.id === activeOrderId ? 'bg-gray-800 text-white border-gray-800 shadow-md' : 'bg-white border-gray-200 hover:border-gray-300 hover:bg-gray-50'}`}
                    >
                        <div className="flex items-center gap-2">
                            <span className={`w-5 h-5 flex items-center justify-center rounded text-[10px] font-bold ${order.id === activeOrderId ? 'bg-gray-600 text-white' : 'bg-gray-200 text-gray-600'}`}>
                                {idx + 1}
                            </span>
                            <span className="text-sm font-medium truncate w-20 md:w-auto">
                                订单 {idx + 1}
                            </span>
                        </div>
                        <div className="flex items-center gap-2">
                            <span className={`font-mono text-xs ${order.id === activeOrderId ? 'text-gray-300' : 'text-gray-500'}`}>
                                ¥{((order.items.reduce((s,i)=>s+i.price,0) + order.tax)).toFixed(0)}
                            </span>
                            {/* Delete Button (Only show on hover or if not active to avoid accidental clicks, but need a way to remove) */}
                            {orders.length > 1 && (
                                <button 
                                    onClick={(e) => { e.stopPropagation(); onDeleteOrder(order.id); }}
                                    className={`p-1 rounded hover:bg-red-500 hover:text-white transition ${order.id === activeOrderId ? 'text-gray-500' : 'text-gray-300'}`}
                                >
                                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                </button>
                            )}
                        </div>
                    </div>
                ))}

                {/* Add Order Button */}
                <button 
                    onClick={onAddOrder}
