import React from 'react';
import { BillState } from '../types';

interface ResultViewProps {
  state: BillState;
  onReset: () => void;
  onBackToEdit: () => void;
}

export const ResultView: React.FC<ResultViewProps> = ({ state, onReset, onBackToEdit }) => {
  const { orders, participants } = state;

  // 1. Calculate Total Bill (Sum of all orders)
  const totalBill = orders.reduce((total, order) => {
    const orderItemsTotal = order.items.reduce((s, i) => s + i.price, 0);
    return total + orderItemsTotal + order.tax;
  }, 0);

  // 2. Calculate Net Balances by aggregating all orders
  const netBalances: Record<string, number> = {};
  participants.forEach(p => netBalances[p.id] = 0);

  orders.forEach(order => {
    const orderItemsTotal = order.items.reduce((s, i) => s + i.price, 0);
    const orderFinalTotal = orderItemsTotal + order.tax;

    // Calculate consumption per person for THIS order
    const consumption: Record<string, number> = {};
    participants.forEach(p => consumption[p.id] = 0);

    order.items.forEach(item => {
      if (item.assignedTo.length > 0) {
        const splitPrice = item.price / item.assignedTo.length;
        item.assignedTo.forEach(pid => {
          if (consumption[pid] !== undefined) consumption[pid] += splitPrice;
        });
      } else {
        const splitPrice = item.price / participants.length;
        participants.forEach(p => consumption[p.id] += splitPrice);
      }
    });

    const ratio = orderItemsTotal > 0 ? (orderFinalTotal / orderItemsTotal) : (orderFinalTotal / participants.length);

    participants.forEach(p => {
      const shouldPay = orderItemsTotal > 0 ? (consumption[p.id] * ratio) : (orderFinalTotal / participants.length);

      netBalances[p.id] -= shouldPay;

      if (p.id === order.payerId) {
        netBalances[p.id] += orderFinalTotal;
      }
    });
  });

  return (
    <div className="w-full h-full md:h-[85vh] max-w-2xl mx-auto bg-white md:rounded-xl shadow-lg overflow-hidden flex flex-col md:border border-gray-100">

      {/* Header Result Card */}
      <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 md:p-8 text-white shrink-0 shadow-md z-10 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-5 rounded-full -mr-10 -mt-10 pointer-events-none"></div>

        <div className="relative z-10">
          <div className="flex justify-between items-start mb-4">
             <h2 className="text-xl md:text-2xl font-bold opacity-90">总账单结果</h2>
             <div className="bg-white/10 px-3 py-1 rounded-full text-xs font-medium border border-white/20">
               共 {orders.length} 笔订单
             </div>
          </div>

          <div>
              <p className="text-indigo-200 text-xs md:text-sm uppercase tracking-wider mb-1">所有订单总额</p>
              <div className="flex items-baseline gap-1">
                  <span className="text-2xl">¥</span>
                  <span className="font-mono font-bold text-4xl md:text-5xl">{totalBill.toFixed(2)}</span>
              </div>
          </div>
        </div>
      </div>

      {/* Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 bg-gray-50">

        {/* Person Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 md:gap-4">
           {participants.map(person => {
             const balance = netBalances[person.id];
             const isReceiver = balance > 0.01; 
             const isPayer = balance < -0.01; 
             const isSettled = Math.abs(balance) <= 0.01;

             return (
               <div key={person.id} className={`rounded-xl p-4 relative shadow-sm transition-all border ${isReceiver ? 'bg-white border-green-200 ring-1 ring-green-50' : isSettled ? 'bg-gray-50 border-gray-200 opacity-70' : 'bg-white border-red-100'}`}>
                  <div className="flex justify-between items-center mb-3">
                    <div className="flex items-center gap-2">
                        <div className={`w-2 h-8 rounded-full ${isReceiver ? 'bg-green-500' : isPayer ? 'bg-red-500' : 'bg-gray-300'}`}></div>
                        <h3 className="font-bold text-base text-gray-800">{person.name}</h3>
                    </div>
                    {isReceiver && <span className="bg-green-100 text-green-700 text-[10px] font-bold px-2 py-0.5 rounded-full">收款方</span>}
                  </div>

                  <div className="flex justify-between items-end">
                      <div className="text-right w-full">
                        <p className="text-xs font-medium text-gray-400 mb-0.5">
                            {isReceiver ? '应收回' : isPayer ? '需支付' : '已结清'}
                        </p>
                        <p className={`font-mono font-bold text-xl ${isReceiver ? 'text-green-600' : isPayer ? 'text-red-500' : 'text-gray-400'}`}>
                            {isSettled ? '¥0.00' : `¥${Math.abs(balance).toFixed(2)}`}
                        </p>
                      </div>
                  </div>
               </div>
             );
           })}
        </div>

        {/* Transfer Scheme */}
        <div className="bg-white rounded-xl p-5 border border-gray-200 shadow-sm">
          <h3 className="font-bold text-gray-700 mb-4 flex items-center gap-2 text-sm uppercase tracking-wide">
            <svg className="w-4 h-4 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /></svg>
            最优转账方案
          </h3>
          <ul className="space-y-3">
             {(() => {
                const debtors = participants.filter(p => netBalances[p.id] < -0.01).map(p => ({ id: p.id, name: p.name, amount: -netBalances[p.id] }));
                const creditors = participants.filter(p => netBalances[p.id] > 0.01).map(p => ({ id: p.id, name: p.name, amount: netBalances[p.id] }));

                debtors.sort((a,b) => b.amount - a.amount);
                creditors.sort((a,b) => b.amount - a.amount);

                const transfers = [];
                let i = 0; 
                let j = 0;

                while(i < debtors.length && j < creditors.length) {
                    const debtor = debtors[i];
                    const creditor = creditors[j];

                    const amount = Math.min(debtor.amount, creditor.amount);
                    if (amount > 0.01) {
                        transfers.push({ from: debtor.name, to: creditor.name, amount });
                    }

                    debtor.amount -= amount;
                    creditor.amount -= amount;

                    if (debtor.amount < 0.01) i++;
                    if (creditor.amount < 0.01) j++;
                }

                if (transfers.length === 0) {
                    return <li className="text-gray-400 text-sm text-center py-2">无需转账，帐平了！</li>
                }

                return transfers.map((t, idx) => (
                    <li key={idx} className="flex items-center justify-between border-b border-gray-50 pb-2 last:border-0 last:pb-0">
                        <div className="flex items-center gap-2 text-sm">
                            <span className="font-bold text-gray-800">{t.from}</span>
                            <span className="text-gray-400 text-xs">支付给</span>
                            <span className="font-bold text-gray-800">{t.to}</span>
                        </div>
                        <span className="font-mono font-bold text-indigo-600 bg-indigo-50 px-2 py-1 rounded text-sm">¥{t.amount.toFixed(2)}</span>
                    </li>
                ));
             })()}
          </ul>
        </div>
      </div>

      {/* Footer Actions */}
      <div className="p-4 bg-white border-t border-gray-100 flex flex-col gap-3 shrink-0 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
         <button 
          onClick={onBackToEdit}
          className="w-full py-3 px-4 bg-gray-900 text-white font-semibold rounded-xl hover:bg-gray-800 active:bg-black transition shadow-md flex items-center justify-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
          返回编辑订单
        </button>
        <button 
          onClick={onReset}
          className="w-full py-3 px-4 bg-white border border-gray-200 text-red-500 font-semibold rounded-xl hover:bg-red-50 active:bg-red-100 transition shadow-sm text-sm"
        >
          清空所有数据重新开始
        </button>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { Spinner } from './Spinner';

interface ReceiptUploaderProps {
  onImageSelected: (base64: string) => Promise<void>;
  isProcessing: boolean;
  id?: string; // Optional ID to trigger from outside
}

export const ReceiptUploader: React.FC<ReceiptUploaderProps> = ({ onImageSelected, isProcessing, id }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [dragActive, setDragActive] = useState(false);

  // Allow external trigger if ID is provided
  useEffect(() => {
    if (id) {
        const trigger = document.getElementById(id);
        if (trigger) {
            trigger.onclick = () => fileInputRef.current?.click();
        }
    }
  }, [id]);

  const handleFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
      alert('请上传图片文件');
      return;
    }

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      const base64Data = base64.split(',')[1]; 
      await onImageSelected(base64Data);
    };
    reader.readAsDataURL(file);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(true);
  };

  const onDragLeave = () => {
    setDragActive(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  return (
    <div id={id} className={`w-full max-w-lg mx-auto text-center`}> 
      {/* If used as hidden trigger, we only render the input */}
      <input 
          type="file" 
          ref={fileInputRef}
          className="hidden" 
          accept="image/*"
          onChange={(e) => e.target.files && handleFile(e.target.files[0])}
      />

      {!id && (
        <>
            <div 
                className={`
                relative border-2 border-dashed rounded-2xl p-10 transition-all duration-300
                ${dragActive ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 bg-white'}
                ${isProcessing ? 'opacity-80 pointer-events-none' : 'hover:border-indigo-400'}
                `}
                onDragOver={onDragOver}
                onDragLeave={onDragLeave}
                onDrop={onDrop}
            >

                {isProcessing ? (
                <div className="flex flex-col items-center justify-center py-8">
                    <div className="bg-indigo-600 p-3 rounded-full mb-4 shadow-lg shadow-indigo-200">
                    <Spinner />
                    </div>
                    <h3 className="text-xl font-bold text-gray-800">正在分析小票...</h3>
                    <p className="text-gray-500 mt-2">AI 正在努力识别菜品和价格</p>
                </div>
                ) : (
                <div className="flex flex-col items-center py-4">
                    <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center mb-4 text-indigo-600">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    </div>
                    <h3 className="text-lg font-bold text-gray-800 mb-2">上传小票</h3>
                    <p className="text-gray-500 text-sm mb-6 max-w-xs">将小票图片拖拽至此，或点击选择</p>
                    <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="bg-gray-900 text-white px-6 py-3 rounded-lg font-semibold shadow-lg hover:bg-gray-800 transition transform active:scale-95"
                    >
                    选择图片
                    </button>
                </div>
                )}
            </div>

            {!isProcessing && (
                <button 
                onClick={() => onImageSelected('')} // Pass empty to skip AI
                className="mt-6 text-indigo-600 font-medium text-sm hover:underline"
                >
                跳过，手动输入
                </button>
            )}
        </>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { AppStep, Order, Participant, ReceiptItem } from './types';
import { ReceiptUploader } from './components/ReceiptUploader';
import { EditorView } from './components/EditorView';
import { ResultView } from './components/ResultView';
import { parseReceiptImage } from './services/geminiService';

const DEFAULT_PARTICIPANTS: Participant[] = [
  { id: '1', name: '我' },
  { id: '2', name: '朋友 A' },
  { id: '3', name: '朋友 B' },
  { id: '4', name: '朋友 C' },
];

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.UPLOAD);
  const [isProcessing, setIsProcessing] = useState(false);

  // Global State
  const [participants, setParticipants] = useState<Participant[]>(DEFAULT_PARTICIPANTS);
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeOrderId, setActiveOrderId] = useState<string | null>(null);

  // Modal State
  const [showAddOrderModal, setShowAddOrderModal] = useState(false);

  // --- Initial Upload ---
  const handleInitialUpload = async (base64Data: string) => {
    await createNewOrder(base64Data);
    setStep(AppStep.EDIT_AND_ASSIGN);
  };

  // --- Core Logic ---

  const createNewOrder = async (base64Data: string) => {
    let newItems: Partial<ReceiptItem>[] = [];

    if (base64Data) {
      setIsProcessing(true);
      try {
        newItems = await parseReceiptImage(base64Data);
      } catch (error) {
        alert("识别小票失败，转为手动输入。");
      } finally {
        setIsProcessing(false);
      }
    }

    const newOrder: Order = {
      id: crypto.randomUUID(),
      // Ensure items have full structure
      items: newItems.map(i => ({
        id: i.id || crypto.randomUUID(),
        name: i.name || '新商品',
        price: i.price || 0,
        assignedTo: participants.map(p => p.id) // Default assign to all
      })) as ReceiptItem[],
      tax: 0,
      payerId: participants[0]?.id || '1', // Default payer
      timestamp: Date.now(),
    };

    setOrders(prev => [...prev, newOrder]);
    setActiveOrderId(newOrder.id);
    setStep(AppStep.EDIT_AND_ASSIGN); // Ensure we go to edit view
  };

  const handleUpdateOrder = (updatedOrder: Order) => {
    setOrders(prev => prev.map(o => o.id === updatedOrder.id ? updatedOrder : o));
  };

  const handleDeleteOrder = (orderId: string) => {
    if (orders.length <= 1) {
      if (window.confirm("这是最后一笔订单，删除将清空并返回首页，确定吗？")) {
         handleReset();
      }
      return;
    }
    const newOrders = orders.filter(o => o.id !== orderId);
    setOrders(newOrders);
    if (activeOrderId === orderId) {
      setActiveOrderId(newOrders[0].id);
    }
  };

  const handleAddOrderRequest = () => {
    setShowAddOrderModal(true);
  };

  const handleAddOrderConfirm = async (base64: string) => {
    setShowAddOrderModal(false);
    await createNewOrder(base64);
  };

  const handleReset = () => {
    setStep(AppStep.UPLOAD);
    setOrders([]);
    setParticipants(DEFAULT_PARTICIPANTS);
    setActiveOrderId(null);
  };

  const handleViewResults = () => {
     setStep(AppStep.RESULT);
  };

  return (
    <div className="fixed inset-0 bg-gray-50 text-gray-800 font-sans flex flex-col overflow-hidden">

      {/* Header */}
      <header className="px-4 py-3 md:p-6 bg-white shadow-sm shrink-0 z-20 relative">
        <div className="max-w-7xl mx-auto flex items-center gap-3">
          <div className="w-8 h-8 md:w-10 md:h-10 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold text-lg md:text-xl shadow-lg">
            AA
          </div>
          <h1 className="text-lg md:text-xl font-bold tracking-tight text-gray-900">AA Pay</h1>
          {orders.length > 0 && (
            <span className="ml-2 px-2 py-0.5 bg-gray-100 text-gray-500 text-xs rounded-full border border-gray-200">
              {orders.length} 笔订单
            </span>
          )}
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative w-full max-w-6xl mx-auto md:p-6">

        {step === AppStep.UPLOAD && (
          <div className="w-full h-full overflow-y-auto p-4 animate-fade-in-up">
            <div className="text-center mb-6 md:mb-10 mt-4 md:mt-10">
              <h2 className="text-2xl md:text-4xl font-extrabold text-gray-900 mb-2 md:mb-4">轻松搞定聚餐算账</h2>
              <p className="text-sm md:text-lg text-gray-600 max-w-2xl mx-auto">
                上传小票截图或照片，AI 自动识别菜品，支持多人多订单合并计算。
              </p>
            </div>
            <ReceiptUploader onImageSelected={handleInitialUpload} isProcessing={isProcessing} />
          </div>
        )}

        {step === AppStep.EDIT_AND_ASSIGN && activeOrderId && (
          <div className="w-full h-full animate-fade-in">
             <EditorView 
                key={activeOrderId} // Key forces re-mount when order changes, ensuring clean input state
                orders={orders}
                activeOrderId={activeOrderId}
                participants={participants}
                onUpdateParticipants={setParticipants}
                onUpdateOrder={handleUpdateOrder}
                onSelectOrder={setActiveOrderId}
                onAddOrder={handleAddOrderRequest}
                onDeleteOrder={handleDeleteOrder}
                onViewResult={handleViewResults}
             />
          </div>
        )}

        {step === AppStep.RESULT && (
          <div className="w-full h-full animate-fade-in">
            <ResultView 
              state={{ orders, participants }} 
              onReset={handleReset} 
              onBackToEdit={() => setStep(AppStep.EDIT_AND_ASSIGN)}
